-- Aprenda se Divertindo · 77 · Baralho de cartões · trilha Enem (500 cartões)
-- Rode depois do 76-cartoes-policial-2.sql. Cole TUDO no SQL Editor e clique em Run. Pode rodar de novo sem problema.
--
-- Linguagens (literatura, gêneros, figuras, redação, artes), Matemática, Física, Química, Biologia, História,
-- Geografia e Filosofia/Sociologia, no mesmo formato dos cartões da trilha Policial.
-- Os cartões valem por matéria: quem estuda Português ou Raciocínio Lógico em qualquer trilha já usa os cartões existentes;
-- matérias sem cartões continuam com as questões do jogo.
-- Cartões numerados de 2.000.001.001 a 2.000.001.500. O jogo baixa os novos cartões sozinho.

insert into public.cartoes (id, trilha, materia, assunto, tipo, frente, verso, explicacao)
select id, trilha, materia, assunto, tipo, frente, verso, explicacao
from jsonb_to_recordset($c$[{"id": 2000001001, "trilha": "enem", "materia": "ling", "assunto": "Funções da linguagem", "tipo": "pergunta", "frente": "Qual função da linguagem predomina numa propaganda que diz “Compre já!”?", "verso": "Conativa (ou apelativa): o foco é convencer o receptor.", "explicacao": "Marcas: verbos no imperativo e vocativos."}, {"id": 2000001002, "trilha": "enem", "materia": "ling", "assunto": "Funções da linguagem", "tipo": "pergunta", "frente": "Qual função predomina numa notícia de jornal?", "verso": "Referencial (ou denotativa): foco na informação, no assunto.", "explicacao": "Linguagem objetiva, em 3ª pessoa."}, {"id": 2000001003, "trilha": "enem", "materia": "ling", "assunto": "Funções da linguagem", "tipo": "pergunta", "frente": "Qual função predomina num diário íntimo ou num desabafo?", "verso": "Emotiva (ou expressiva): foco no emissor e em seus sentimentos.", "explicacao": "Marcas: 1ª pessoa, interjeições, exclamações."}, {"id": 2000001004, "trilha": "enem", "materia": "ling", "assunto": "Funções da linguagem", "tipo": "pergunta", "frente": "O que é a função fática?", "verso": "A que testa ou mantém o canal de comunicação: “Alô?”, “Tá me ouvindo?”, “Bom dia”.", "explicacao": "Foco no canal."}, {"id": 2000001005, "trilha": "enem", "materia": "ling", "assunto": "Funções da linguagem", "tipo": "pergunta", "frente": "O que é a função metalinguística?", "verso": "A linguagem falando de si mesma: verbete de dicionário, poema sobre o ato de escrever, filme sobre cinema.", "explicacao": "Foco no código."}, {"id": 2000001006, "trilha": "enem", "materia": "ling", "assunto": "Funções da linguagem", "tipo": "pergunta", "frente": "O que caracteriza a função poética?", "verso": "Foco na própria mensagem: o trabalho com a forma, o som e o ritmo das palavras.", "explicacao": "Aparece também em slogans e trava-línguas."}, {"id": 2000001007, "trilha": "enem", "materia": "ling", "assunto": "Variação linguística", "tipo": "pares", "frente": "Variação diatópica x diastrática x diafásica.", "verso": "Diatópica: por região (sotaques, “mandioca/aipim/macaxeira”). Diastrática: por grupo social, idade, profissão (gírias, jargões). Diafásica: por situação (formal x informal).", "explicacao": "Há também a diacrônica: mudança ao longo do tempo."}, {"id": 2000001008, "trilha": "enem", "materia": "ling", "assunto": "Variação linguística", "tipo": "pergunta", "frente": "O que é preconceito linguístico?", "verso": "Julgar pessoas como inferiores pelo modo como falam, tratando a norma-padrão como única forma “correta”.", "explicacao": "O Enem valoriza a ideia de adequação ao contexto, não de “certo e errado”."}, {"id": 2000001009, "trilha": "enem", "materia": "ling", "assunto": "Variação linguística", "tipo": "certo_errado", "frente": "Certo ou errado? Para o Enem, a variedade popular é um erro que deve ser corrigido em qualquer situação.", "verso": "Errado. Toda variedade é legítima; o que importa é a adequação à situação de comunicação.", "explicacao": "A norma-padrão é exigida em situações formais, como a redação."}, {"id": 2000001010, "trilha": "enem", "materia": "ling", "assunto": "Variação linguística", "tipo": "pergunta", "frente": "O que é variação diacrônica? Dê um exemplo.", "verso": "A mudança da língua ao longo do tempo. Ex.: “Vossa Mercê” → “vosmecê” → “você” → “cê”.", "explicacao": "Textos antigos costumam ilustrar essa variação."}, {"id": 2000001011, "trilha": "enem", "materia": "ling", "assunto": "Gêneros textuais", "tipo": "pares", "frente": "Tipo textual x gênero textual.", "verso": "Tipo: estrutura linguística (narração, descrição, dissertação, injunção, exposição). Gênero: texto concreto do dia a dia (receita, notícia, crônica, bula).", "explicacao": "Uma receita é um gênero de tipo predominantemente injuntivo."}, {"id": 2000001012, "trilha": "enem", "materia": "ling", "assunto": "Gêneros textuais", "tipo": "pergunta", "frente": "Quais as características da crônica?", "verso": "Texto curto, sobre fatos do cotidiano, com linguagem leve, tom pessoal e muitas vezes humor ou reflexão.", "explicacao": "Publicada originalmente em jornais e revistas."}, {"id": 2000001013, "trilha": "enem", "materia": "ling", "assunto": "Gêneros textuais", "tipo": "pergunta", "frente": "Qual a diferença entre notícia e reportagem?", "verso": "Notícia: relato breve e objetivo de um fato recente. Reportagem: aprofunda o tema, com dados, entrevistas e análise.", "explicacao": "Ambas são gêneros jornalísticos."}, {"id": 2000001014, "trilha": "enem", "materia": "ling", "assunto": "Gêneros textuais", "tipo": "pergunta", "frente": "O que é um texto injuntivo?", "verso": "O que orienta o leitor a fazer algo, com instruções: receitas, manuais, bulas.", "explicacao": "Verbos no imperativo ou no infinitivo."}, {"id": 2000001015, "trilha": "enem", "materia": "ling", "assunto": "Gêneros textuais", "tipo": "pergunta", "frente": "O que é um artigo de opinião?", "verso": "Texto argumentativo assinado, em que o autor defende um ponto de vista sobre um tema atual.", "explicacao": "Diferente do editorial, que expressa a opinião do veículo e não é assinado."}, {"id": 2000001016, "trilha": "enem", "materia": "ling", "assunto": "Gêneros textuais", "tipo": "pergunta", "frente": "O que é charge?", "verso": "Desenho humorístico que critica um fato ou personagem atual, geralmente da política.", "explicacao": "Exige conhecer o contexto da época para ser entendida."}, {"id": 2000001017, "trilha": "enem", "materia": "ling", "assunto": "Gêneros textuais", "tipo": "pares", "frente": "Charge x cartum.", "verso": "Charge: critica um fato específico e datado. Cartum: humor atemporal, sem depender de um acontecimento concreto.", "explicacao": "Tirinhas (HQs) contam uma pequena história em quadrinhos."}, {"id": 2000001018, "trilha": "enem", "materia": "ling", "assunto": "Intertextualidade", "tipo": "pares", "frente": "Paródia x paráfrase.", "verso": "Paródia: retoma um texto com sentido crítico ou humorístico, subvertendo-o. Paráfrase: reescreve com outras palavras mantendo o sentido original.", "explicacao": "A “Canção do exílio” de Gonçalves Dias tem muitas paródias."}, {"id": 2000001019, "trilha": "enem", "materia": "ling", "assunto": "Intertextualidade", "tipo": "pergunta", "frente": "O que é intertextualidade?", "verso": "O diálogo entre textos: quando um texto retoma, cita ou alude a outro.", "explicacao": "Formas: citação, alusão, paródia, paráfrase, epígrafe."}, {"id": 2000001020, "trilha": "enem", "materia": "ling", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é metonímia?", "verso": "Troca de um termo por outro com o qual mantém relação de proximidade: autor pela obra (“li Machado”), marca pelo produto, parte pelo todo.", "explicacao": "Diferente da metáfora, que se baseia em semelhança."}, {"id": 2000001021, "trilha": "enem", "materia": "ling", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é ironia?", "verso": "Dizer o contrário do que se pensa, com intenção crítica ou humorística.", "explicacao": "Muito cobrada em charges e crônicas."}, {"id": 2000001022, "trilha": "enem", "materia": "ling", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é eufemismo?", "verso": "Suavizar uma expressão desagradável: “ele partiu” em vez de “ele morreu”.", "explicacao": "O oposto é a hipérbole, que exagera."}, {"id": 2000001023, "trilha": "enem", "materia": "ling", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é prosopopeia (personificação)?", "verso": "Atribuir características humanas a seres inanimados ou animais: “o vento sussurrava”.", "explicacao": ""}, {"id": 2000001024, "trilha": "enem", "materia": "ling", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é sinestesia?", "verso": "Mistura de sensações de sentidos diferentes: “voz doce”, “cor gritante”.", "explicacao": "Muito presente no Simbolismo."}, {"id": 2000001025, "trilha": "enem", "materia": "ling", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é aliteração?", "verso": "Repetição de sons consonantais: “o rato roeu a roupa do rei de Roma”.", "explicacao": "Assonância é a repetição de sons vocálicos."}, {"id": 2000001026, "trilha": "enem", "materia": "ling", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é hipérbole?", "verso": "Exagero intencional: “chorei rios de lágrimas”.", "explicacao": ""}, {"id": 2000001027, "trilha": "enem", "materia": "ling", "assunto": "Coesão", "tipo": "pergunta", "frente": "O que são conectivos adversativos? Cite exemplos.", "verso": "Ligam ideias de oposição: mas, porém, contudo, todavia, no entanto, entretanto.", "explicacao": "Mudar o conectivo pode mudar o sentido da frase."}, {"id": 2000001028, "trilha": "enem", "materia": "ling", "assunto": "Coesão", "tipo": "pergunta", "frente": "Que relação expressam “portanto”, “logo” e “por isso”?", "verso": "Conclusão.", "explicacao": "Conectivos conclusivos."}, {"id": 2000001029, "trilha": "enem", "materia": "ling", "assunto": "Coesão", "tipo": "pergunta", "frente": "Que relação expressam “embora”, “ainda que” e “mesmo que”?", "verso": "Concessão: admite um fato contrário que não impede o outro.", "explicacao": "Pedem verbo no subjuntivo."}, {"id": 2000001030, "trilha": "enem", "materia": "ling", "assunto": "Coesão", "tipo": "pares", "frente": "Coesão x coerência.", "verso": "Coesão: ligação formal entre as partes do texto (pronomes, conectivos, sinônimos). Coerência: lógica e sentido do conjunto.", "explicacao": "Um texto pode ser coeso e incoerente."}, {"id": 2000001031, "trilha": "enem", "materia": "ling", "assunto": "Interpretação", "tipo": "pares", "frente": "Denotação x conotação.", "verso": "Denotação: sentido literal, de dicionário. Conotação: sentido figurado, que depende do contexto.", "explicacao": "“Ele tem um coração de pedra” é conotativo."}, {"id": 2000001032, "trilha": "enem", "materia": "ling", "assunto": "Interpretação", "tipo": "pergunta", "frente": "O que é a tese de um texto argumentativo?", "verso": "A ideia principal que o autor defende.", "explicacao": "Costuma aparecer na introdução."}, {"id": 2000001033, "trilha": "enem", "materia": "ling", "assunto": "Interpretação", "tipo": "pergunta", "frente": "O que são argumentos de autoridade?", "verso": "Citar especialista, instituição ou pesquisa reconhecida para dar credibilidade à tese.", "explicacao": "Outros tipos: exemplificação, dados estatísticos, causa e consequência."}, {"id": 2000001034, "trilha": "enem", "materia": "ling", "assunto": "Interpretação", "tipo": "pergunta", "frente": "O que é inferência na leitura?", "verso": "Concluir algo que não está escrito, mas pode ser deduzido pelas pistas do texto.", "explicacao": "Diferente de extrapolar, que é concluir além do que o texto permite."}, {"id": 2000001035, "trilha": "enem", "materia": "ling", "assunto": "Redação", "tipo": "pergunta", "frente": "Quantas competências avalia a redação do Enem e quanto vale cada uma?", "verso": "Cinco competências, de 0 a 200 pontos cada, num total de 1.000.", "explicacao": "Corrigida por dois avaliadores."}, {"id": 2000001036, "trilha": "enem", "materia": "ling", "assunto": "Redação", "tipo": "pergunta", "frente": "O que avalia a competência 1 da redação do Enem?", "verso": "O domínio da modalidade escrita formal da língua portuguesa.", "explicacao": "Gramática, ortografia, acentuação, pontuação."}, {"id": 2000001037, "trilha": "enem", "materia": "ling", "assunto": "Redação", "tipo": "pergunta", "frente": "O que avalia a competência 5 da redação do Enem?", "verso": "A proposta de intervenção para o problema, respeitando os direitos humanos.", "explicacao": "Elementos esperados: agente, ação, modo/meio, finalidade e detalhamento."}, {"id": 2000001038, "trilha": "enem", "materia": "ling", "assunto": "Redação", "tipo": "pergunta", "frente": "Qual o tipo textual exigido na redação do Enem?", "verso": "Dissertativo-argumentativo, em prosa.", "explicacao": "Fugir do tipo leva a nota zero."}, {"id": 2000001039, "trilha": "enem", "materia": "ling", "assunto": "Redação", "tipo": "pergunta", "frente": "Quando a redação do Enem recebe nota zero?", "verso": "Fuga total do tema, tipo textual diferente, até 7 linhas, cópia dos textos motivadores, parte desconectada, folha em branco, entre outros.", "explicacao": "Desrespeito aos direitos humanos zera a competência 5."}, {"id": 2000001040, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quais as características do Quinhentismo no Brasil?", "verso": "Textos informativos sobre a nova terra (carta de Caminha) e literatura jesuíta de catequese (José de Anchieta).", "explicacao": "Não é literatura brasileira propriamente dita; é literatura sobre o Brasil."}, {"id": 2000001041, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem é o principal poeta do Barroco brasileiro e qual sua marca?", "verso": "Gregório de Matos, o “Boca do Inferno”, com poesia satírica, lírica e religiosa.", "explicacao": "Barroco: conflito, antíteses, paradoxos, cultismo e conceptismo."}, {"id": 2000001042, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quais as características do Arcadismo?", "verso": "Bucolismo, valorização da vida no campo, pastoralismo, simplicidade, “fugere urbem” e “carpe diem”.", "explicacao": "Autores: Cláudio Manuel da Costa e Tomás Antônio Gonzaga (“Marília de Dirceu”)."}, {"id": 2000001043, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pares", "frente": "Primeira x segunda x terceira geração romântica (poesia).", "verso": "1ª: nacionalista e indianista (Gonçalves Dias). 2ª: ultrarromântica, mal do século, pessimismo (Álvares de Azevedo). 3ª: condoreira, social, abolicionista (Castro Alves).", "explicacao": "Castro Alves: “O navio negreiro”."}, {"id": 2000001044, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Qual a principal obra indianista em prosa de José de Alencar?", "verso": "“Iracema” (e também “O guarani” e “Ubirajara”).", "explicacao": "O índio idealizado como herói nacional."}, {"id": 2000001045, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quais as características do Realismo?", "verso": "Objetividade, crítica social, análise psicológica, combate à idealização romântica.", "explicacao": "Machado de Assis inaugura o Realismo com “Memórias póstumas de Brás Cubas” (1881)."}, {"id": 2000001046, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pares", "frente": "Realismo x Naturalismo.", "verso": "Realismo: foco psicológico, crítica à burguesia (Machado de Assis). Naturalismo: determinismo biológico e social, personagens movidas por instintos (Aluísio Azevedo, “O cortiço”).", "explicacao": "Ambos reagem ao Romantismo."}, {"id": 2000001047, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem narra “Dom Casmurro” e qual o grande enigma da obra?", "verso": "Bentinho (Dom Casmurro), em primeira pessoa; o enigma é se Capitu o traiu ou não.", "explicacao": "Narrador não confiável."}, {"id": 2000001048, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quais as características do Parnasianismo?", "verso": "Arte pela arte, culto da forma, rigor métrico, sonetos, vocabulário erudito e objetividade.", "explicacao": "Olavo Bilac é o principal nome."}, {"id": 2000001049, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quais as características do Simbolismo?", "verso": "Musicalidade, subjetividade, misticismo, sinestesias e uso de maiúsculas alegorizantes.", "explicacao": "Cruz e Sousa (“Broquéis”) e Alphonsus de Guimaraens."}, {"id": 2000001050, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "O que é o Pré-Modernismo? Cite autores.", "verso": "Período de transição (1902–1922) com foco na realidade brasileira e crítica social: Euclides da Cunha (“Os sertões”), Lima Barreto (“Triste fim de Policarpo Quaresma”), Monteiro Lobato.", "explicacao": "Augusto dos Anjos é o poeta do período."}, {"id": 2000001051, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "O que foi a Semana de Arte Moderna?", "verso": "Evento de 1922, em São Paulo, que marcou o início do Modernismo, propondo ruptura com o academicismo e valorização da cultura nacional.", "explicacao": "Nomes: Mário de Andrade, Oswald de Andrade, Anita Malfatti."}, {"id": 2000001052, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "O que propunha o “Manifesto Antropófago” (1928)?", "verso": "Devorar a cultura estrangeira e transformá-la em algo brasileiro, original.", "explicacao": "Oswald de Andrade: “Tupi or not tupi, that is the question”."}, {"id": 2000001053, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quais as marcas da 1ª fase do Modernismo (1922–1930)?", "verso": "Verso livre, linguagem coloquial, humor, poema-piada, ruptura com a tradição e nacionalismo crítico.", "explicacao": "“Macunaíma”, de Mário de Andrade."}, {"id": 2000001054, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "O que caracteriza o romance de 30?", "verso": "Regionalismo e crítica social, especialmente sobre o Nordeste: seca, coronelismo, miséria.", "explicacao": "Graciliano Ramos (“Vidas secas”), Rachel de Queiroz (“O quinze”), Jorge Amado."}, {"id": 2000001055, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quais os temas da poesia de Carlos Drummond de Andrade?", "verso": "O indivíduo e o mundo, o cotidiano, a família, a terra natal (Itabira), o amor e as questões sociais, com ironia.", "explicacao": "“No meio do caminho tinha uma pedra”."}, {"id": 2000001056, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "O que marca a obra de Guimarães Rosa?", "verso": "Invenção de palavras (neologismos), linguagem do sertão e temas universais.", "explicacao": "“Grande sertão: veredas”."}, {"id": 2000001057, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "O que marca a obra de Clarice Lispector?", "verso": "Introspecção, fluxo de consciência, epifania (revelação súbita em momentos banais).", "explicacao": "“A hora da estrela”, com a nordestina Macabéa."}, {"id": 2000001058, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "O que é a poesia concreta?", "verso": "Movimento dos anos 1950 que explora a forma visual da palavra na página, abolindo o verso tradicional.", "explicacao": "Irmãos Campos e Décio Pignatari."}, {"id": 2000001059, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Qual o tema de “Morte e vida severina”, de João Cabral de Melo Neto?", "verso": "A saga do retirante Severino, que foge da seca rumo ao Recife e encontra a morte por todo o caminho.", "explicacao": "Auto de Natal pernambucano."}, {"id": 2000001060, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "Quem é Carolina Maria de Jesus?", "verso": "Escritora negra, moradora da favela do Canindé, autora de “Quarto de despejo” (1960), diário sobre a fome e a pobreza.", "explicacao": "Autora cada vez mais presente no Enem."}, {"id": 2000001061, "trilha": "enem", "materia": "ling", "assunto": "Literatura", "tipo": "pergunta", "frente": "O que caracteriza a literatura marginal ou periférica?", "verso": "Produção de autores das periferias, retratando a realidade desses espaços com sua própria linguagem.", "explicacao": "Ex.: Ferréz, saraus da periferia."}, {"id": 2000001062, "trilha": "enem", "materia": "ling", "assunto": "Artes", "tipo": "pergunta", "frente": "O que foi o Impressionismo na pintura?", "verso": "Movimento do século XIX que buscava captar a luz e a impressão do momento, com pinceladas soltas e pintura ao ar livre.", "explicacao": "Claude Monet, “Impressão, nascer do sol”."}, {"id": 2000001063, "trilha": "enem", "materia": "ling", "assunto": "Artes", "tipo": "pergunta", "frente": "O que caracteriza o Cubismo?", "verso": "Representação de objetos de vários ângulos ao mesmo tempo, com formas geométricas.", "explicacao": "Pablo Picasso, “Les demoiselles d'Avignon” e “Guernica”."}, {"id": 2000001064, "trilha": "enem", "materia": "ling", "assunto": "Artes", "tipo": "pergunta", "frente": "O que caracteriza o Surrealismo?", "verso": "Arte inspirada no inconsciente e nos sonhos, com imagens absurdas e ilógicas.", "explicacao": "Salvador Dalí, “A persistência da memória”."}, {"id": 2000001065, "trilha": "enem", "materia": "ling", "assunto": "Artes", "tipo": "pergunta", "frente": "Qual obra de Tarsila do Amaral inspirou o Movimento Antropofágico?", "verso": "“Abaporu” (1928).", "explicacao": "Abaporu significa “homem que come gente” em tupi."}, {"id": 2000001066, "trilha": "enem", "materia": "ling", "assunto": "Artes", "tipo": "pergunta", "frente": "O que é arte contemporânea de instalação?", "verso": "Obra que ocupa um espaço e propõe a experiência do público dentro dela.", "explicacao": "Valoriza o conceito e a interação, não só o objeto."}, {"id": 2000001067, "trilha": "enem", "materia": "ling", "assunto": "Artes", "tipo": "pergunta", "frente": "Quem foi Aleijadinho?", "verso": "Antônio Francisco Lisboa, escultor e arquiteto do Barroco mineiro (séc. XVIII).", "explicacao": "“Os profetas”, em Congonhas (MG)."}, {"id": 2000001068, "trilha": "enem", "materia": "ling", "assunto": "Artes", "tipo": "pergunta", "frente": "O que foi o Tropicalismo?", "verso": "Movimento cultural do fim dos anos 1960 que misturou cultura popular, rock, MPB e vanguarda, com crítica social e política.", "explicacao": "Caetano Veloso, Gilberto Gil, Os Mutantes."}, {"id": 2000001069, "trilha": "enem", "materia": "ling", "assunto": "Corpo e movimento", "tipo": "pergunta", "frente": "Como o Enem aborda a educação física?", "verso": "Como cultura corporal: esportes, danças, lutas, jogos e ginásticas, com foco em saúde, inclusão e crítica aos padrões de beleza.", "explicacao": "Questões sobre sedentarismo e uso de esteroides são comuns."}, {"id": 2000001070, "trilha": "enem", "materia": "ling", "assunto": "Corpo e movimento", "tipo": "pergunta", "frente": "O que é a capoeira e qual o seu reconhecimento?", "verso": "Expressão afro-brasileira que reúne luta, dança, música e jogo; a roda de capoeira é Patrimônio Cultural Imaterial da Humanidade (Unesco, 2014).", "explicacao": "Também é patrimônio cultural do Brasil."}, {"id": 2000001071, "trilha": "enem", "materia": "ling", "assunto": "Língua estrangeira", "tipo": "pergunta", "frente": "Qual a estratégia básica para as questões de inglês ou espanhol do Enem?", "verso": "Ler primeiro a pergunta, buscar palavras-chave, cognatos e o contexto do gênero; não é preciso traduzir tudo.", "explicacao": "São 5 questões da língua escolhida."}, {"id": 2000001072, "trilha": "enem", "materia": "ling", "assunto": "Língua estrangeira", "tipo": "pergunta", "frente": "O que são falsos cognatos? Dê um exemplo em inglês.", "verso": "Palavras parecidas com o português, mas de sentido diferente: “pretend” significa fingir, não pretender.", "explicacao": "Outros: “actually” (na verdade), “push” (empurrar)."}, {"id": 2000001073, "trilha": "enem", "materia": "ling", "assunto": "Língua estrangeira", "tipo": "pergunta", "frente": "Em espanhol, o que significam “exquisito”, “rato” e “embarazada”?", "verso": "Delicioso; momento (“un rato”); grávida.", "explicacao": "Os chamados “falsos amigos”."}, {"id": 2000001074, "trilha": "enem", "materia": "ling", "assunto": "Língua estrangeira", "tipo": "pergunta", "frente": "Em espanhol, o que significam “pronto”, “oficina” e “polvo”?", "verso": "Logo, em breve; escritório; pó.", "explicacao": "Polvo (animal) em espanhol é “pulpo”."}, {"id": 2000001075, "trilha": "enem", "materia": "ling", "assunto": "Tecnologia e comunicação", "tipo": "pergunta", "frente": "O que são fake news e como identificá-las?", "verso": "Notícias falsas criadas para enganar. Verifique a fonte, a data, o autor, se outros veículos confirmam e desconfie de títulos alarmistas.", "explicacao": "Tema frequente em questões sobre mídia."}, {"id": 2000001076, "trilha": "enem", "materia": "mat", "assunto": "Porcentagem", "tipo": "pergunta", "frente": "Como calcular um aumento de 20% seguido de um desconto de 20%?", "verso": "Multiplique pelos fatores: 1,20 × 0,80 = 0,96. O resultado é uma perda de 4%.", "explicacao": "Aumentos e descontos sucessivos se multiplicam, não se somam."}, {"id": 2000001077, "trilha": "enem", "materia": "mat", "assunto": "Porcentagem", "tipo": "pergunta", "frente": "Qual o fator multiplicativo de um desconto de 15%?", "verso": "0,85.", "explicacao": "Desconto de x%: multiplique por (1 − x/100)."}, {"id": 2000001078, "trilha": "enem", "materia": "mat", "assunto": "Porcentagem", "tipo": "pergunta", "frente": "Um preço subiu de R$ 80 para R$ 100. Qual foi o aumento percentual?", "verso": "25%.", "explicacao": "Variação ÷ valor inicial: 20 ÷ 80 = 0,25."}, {"id": 2000001079, "trilha": "enem", "materia": "mat", "assunto": "Porcentagem", "tipo": "certo_errado", "frente": "Certo ou errado? Dois aumentos seguidos de 10% equivalem a um aumento de 20%.", "verso": "Errado. Equivalem a 21% (1,1 × 1,1 = 1,21).", "explicacao": "Juros sobre juros."}, {"id": 2000001080, "trilha": "enem", "materia": "mat", "assunto": "Porcentagem", "tipo": "pergunta", "frente": "Quanto é 30% de 40% de 500?", "verso": "60.", "explicacao": "0,3 × 0,4 × 500 = 60."}, {"id": 2000001081, "trilha": "enem", "materia": "mat", "assunto": "Juros", "tipo": "pares", "frente": "Juros simples x juros compostos.", "verso": "Simples: J = C·i·t, cresce em linha reta (progressão aritmética). Compostos: M = C·(1 + i)^t, cresce de forma exponencial (progressão geométrica).", "explicacao": "Para t > 1, compostos rendem mais."}, {"id": 2000001082, "trilha": "enem", "materia": "mat", "assunto": "Juros", "tipo": "pergunta", "frente": "R$ 1.000 a juros compostos de 10% ao mês por 2 meses rendem quanto de montante?", "verso": "R$ 1.210.", "explicacao": "1.000 × 1,1² = 1.210."}, {"id": 2000001083, "trilha": "enem", "materia": "mat", "assunto": "Juros", "tipo": "pergunta", "frente": "R$ 2.000 a juros simples de 3% ao mês por 5 meses geram quantos reais de juros?", "verso": "R$ 300.", "explicacao": "J = 2.000 × 0,03 × 5."}, {"id": 2000001084, "trilha": "enem", "materia": "mat", "assunto": "Razão e proporção", "tipo": "pergunta", "frente": "O que é escala num mapa de 1:50.000?", "verso": "Cada 1 cm no mapa equivale a 50.000 cm (500 m) no real.", "explicacao": "Escala = medida no desenho ÷ medida real."}, {"id": 2000001085, "trilha": "enem", "materia": "mat", "assunto": "Razão e proporção", "tipo": "pares", "frente": "Grandezas diretamente x inversamente proporcionais.", "verso": "Diretas: uma dobra, a outra dobra (a razão é constante). Inversas: uma dobra, a outra cai pela metade (o produto é constante).", "explicacao": "Ex. inversa: velocidade e tempo de viagem."}, {"id": 2000001086, "trilha": "enem", "materia": "mat", "assunto": "Razão e proporção", "tipo": "pergunta", "frente": "6 pedreiros fazem um muro em 10 dias. Em quantos dias 4 pedreiros fazem o mesmo muro?", "verso": "15 dias.", "explicacao": "Inversamente proporcional: 6 × 10 = 4 × t."}, {"id": 2000001087, "trilha": "enem", "materia": "mat", "assunto": "Razão e proporção", "tipo": "pergunta", "frente": "Como se calcula a velocidade média?", "verso": "Distância total ÷ tempo total.", "explicacao": "Não é a média das velocidades, a não ser que os tempos sejam iguais."}, {"id": 2000001088, "trilha": "enem", "materia": "mat", "assunto": "Razão e proporção", "tipo": "pergunta", "frente": "Como converter 72 km/h em m/s?", "verso": "Divida por 3,6: 20 m/s.", "explicacao": "De m/s para km/h, multiplique por 3,6."}, {"id": 2000001089, "trilha": "enem", "materia": "mat", "assunto": "Unidades", "tipo": "pergunta", "frente": "Quantos litros cabem em 1 m³?", "verso": "1.000 litros.", "explicacao": "1 dm³ = 1 L."}, {"id": 2000001090, "trilha": "enem", "materia": "mat", "assunto": "Unidades", "tipo": "pergunta", "frente": "Quantos m² tem 1 hectare?", "verso": "10.000 m².", "explicacao": "Um quadrado de 100 m × 100 m."}, {"id": 2000001091, "trilha": "enem", "materia": "mat", "assunto": "Estatística", "tipo": "pares", "frente": "Média x mediana x moda.", "verso": "Média: soma ÷ quantidade. Mediana: valor central dos dados em ordem. Moda: valor mais frequente.", "explicacao": "A mediana é menos afetada por valores extremos."}, {"id": 2000001092, "trilha": "enem", "materia": "mat", "assunto": "Estatística", "tipo": "pergunta", "frente": "Qual a mediana de 3, 8, 5, 10?", "verso": "6,5.", "explicacao": "Ordene (3, 5, 8, 10) e tire a média dos dois centrais."}, {"id": 2000001093, "trilha": "enem", "materia": "mat", "assunto": "Estatística", "tipo": "pergunta", "frente": "O que mede o desvio padrão?", "verso": "O quanto os dados se espalham em torno da média.", "explicacao": "Desvio padrão pequeno = dados homogêneos."}, {"id": 2000001094, "trilha": "enem", "materia": "mat", "assunto": "Estatística", "tipo": "pergunta", "frente": "Como se calcula a média ponderada?", "verso": "Soma de (valor × peso) dividida pela soma dos pesos.", "explicacao": "Usada em notas com pesos diferentes."}, {"id": 2000001095, "trilha": "enem", "materia": "mat", "assunto": "Estatística", "tipo": "certo_errado", "frente": "Certo ou errado? Se todos os valores de um conjunto aumentam 5, o desvio padrão também aumenta 5.", "verso": "Errado. O desvio padrão não muda; só a média aumenta 5.", "explicacao": "Somar constante desloca os dados sem alterar a dispersão."}, {"id": 2000001096, "trilha": "enem", "materia": "mat", "assunto": "Gráficos", "tipo": "pergunta", "frente": "Qual gráfico é mais indicado para mostrar partes de um todo?", "verso": "Gráfico de setores (pizza).", "explicacao": "Para evolução no tempo, gráfico de linhas."}, {"id": 2000001097, "trilha": "enem", "materia": "mat", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Qual a probabilidade de sair um número par num dado comum?", "verso": "1/2 (3 casos favoráveis em 6).", "explicacao": "P = casos favoráveis ÷ casos possíveis."}, {"id": 2000001098, "trilha": "enem", "materia": "mat", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Qual a probabilidade de tirar duas caras em dois lançamentos de moeda?", "verso": "1/4.", "explicacao": "Eventos independentes: multiplique (1/2 × 1/2)."}, {"id": 2000001099, "trilha": "enem", "materia": "mat", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Como se calcula a probabilidade do evento complementar?", "verso": "P(não A) = 1 − P(A).", "explicacao": "Útil para “pelo menos um”."}, {"id": 2000001100, "trilha": "enem", "materia": "mat", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Qual a probabilidade de sair pelo menos uma cara em três lançamentos de moeda?", "verso": "7/8.", "explicacao": "1 − P(nenhuma cara) = 1 − 1/8."}, {"id": 2000001101, "trilha": "enem", "materia": "mat", "assunto": "Probabilidade", "tipo": "pares", "frente": "Eventos “e” x eventos “ou”.", "verso": "“E” (independentes): multiplica as probabilidades. “Ou” (mutuamente exclusivos): soma as probabilidades.", "explicacao": "Se não forem exclusivos: P(A ou B) = P(A) + P(B) − P(A e B)."}, {"id": 2000001102, "trilha": "enem", "materia": "mat", "assunto": "Análise combinatória", "tipo": "pares", "frente": "Arranjo x combinação.", "verso": "Arranjo: a ordem importa (pódio, senhas). Combinação: a ordem não importa (comissões, grupos).", "explicacao": "C(n,p) = n! ÷ [p!(n−p)!]."}, {"id": 2000001103, "trilha": "enem", "materia": "mat", "assunto": "Análise combinatória", "tipo": "pergunta", "frente": "De quantas formas 4 pessoas podem se sentar em fila?", "verso": "24 (4! = 4 × 3 × 2 × 1).", "explicacao": "Permutação simples."}, {"id": 2000001104, "trilha": "enem", "materia": "mat", "assunto": "Análise combinatória", "tipo": "pergunta", "frente": "Quantas comissões de 2 pessoas podem ser formadas com 5 pessoas?", "verso": "10.", "explicacao": "C(5,2) = 5 × 4 ÷ 2."}, {"id": 2000001105, "trilha": "enem", "materia": "mat", "assunto": "Análise combinatória", "tipo": "pergunta", "frente": "Quantos anagramas tem a palavra AMOR?", "verso": "24.", "explicacao": "4 letras distintas: 4!."}, {"id": 2000001106, "trilha": "enem", "materia": "mat", "assunto": "Análise combinatória", "tipo": "pergunta", "frente": "O que diz o princípio fundamental da contagem?", "verso": "Se uma decisão tem m opções e outra tem n, as duas juntas têm m × n possibilidades.", "explicacao": "Ex.: 3 camisas e 4 calças = 12 combinações."}, {"id": 2000001107, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "pergunta", "frente": "No gráfico de f(x) = ax + b, o que representa o “b”?", "verso": "O ponto em que a reta corta o eixo y (coeficiente linear).", "explicacao": "O “a” é a inclinação (coeficiente angular)."}, {"id": 2000001108, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "pergunta", "frente": "Quando a função f(x) = ax + b é decrescente?", "verso": "Quando a < 0.", "explicacao": "Se a > 0, é crescente."}, {"id": 2000001109, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "pergunta", "frente": "Qual a fórmula do x do vértice da parábola y = ax² + bx + c?", "verso": "xv = −b ÷ 2a.", "explicacao": "yv = −Δ ÷ 4a."}, {"id": 2000001110, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "pergunta", "frente": "Quando a parábola tem concavidade para cima?", "verso": "Quando a > 0. Nesse caso o vértice é ponto de mínimo.", "explicacao": "a < 0: concavidade para baixo, vértice é ponto de máximo."}, {"id": 2000001111, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "pergunta", "frente": "Quantas raízes reais tem uma equação do 2º grau com Δ < 0?", "verso": "Nenhuma raiz real.", "explicacao": "Δ > 0: duas raízes; Δ = 0: uma raiz (dupla)."}, {"id": 2000001112, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "lacuna", "frente": "Fórmula de Bhaskara: x = (−b ± √Δ) ÷ ___, com Δ = b² − 4ac.", "verso": "2a.", "explicacao": "Soma das raízes: −b/a; produto: c/a."}, {"id": 2000001113, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "pergunta", "frente": "Que tipo de função descreve uma população que dobra a cada período?", "verso": "Função exponencial: P(t) = P₀ · 2^t.", "explicacao": "Crescimento percentual constante é exponencial."}, {"id": 2000001114, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "pergunta", "frente": "O que é log₂ 8?", "verso": "3, porque 2³ = 8.", "explicacao": "log_b a = x significa b^x = a."}, {"id": 2000001115, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "pergunta", "frente": "Quanto vale log(100) na base 10?", "verso": "2.", "explicacao": "10² = 100."}, {"id": 2000001116, "trilha": "enem", "materia": "mat", "assunto": "Funções", "tipo": "pergunta", "frente": "Qual a propriedade do logaritmo de um produto?", "verso": "log(a·b) = log a + log b.", "explicacao": "log(a/b) = log a − log b; log aⁿ = n·log a."}, {"id": 2000001117, "trilha": "enem", "materia": "mat", "assunto": "Progressões", "tipo": "pergunta", "frente": "Fórmula do termo geral da PA.", "verso": "aₙ = a₁ + (n − 1)·r.", "explicacao": "r é a razão (diferença constante)."}, {"id": 2000001118, "trilha": "enem", "materia": "mat", "assunto": "Progressões", "tipo": "pergunta", "frente": "Fórmula da soma dos termos de uma PA.", "verso": "Sₙ = (a₁ + aₙ)·n ÷ 2.", "explicacao": "A soma de 1 a 100 é 5.050."}, {"id": 2000001119, "trilha": "enem", "materia": "mat", "assunto": "Progressões", "tipo": "pergunta", "frente": "Fórmula do termo geral da PG.", "verso": "aₙ = a₁ · q^(n−1).", "explicacao": "q é a razão (quociente constante)."}, {"id": 2000001120, "trilha": "enem", "materia": "mat", "assunto": "Progressões", "tipo": "pergunta", "frente": "Qual a soma da PG infinita 1 + 1/2 + 1/4 + …?", "verso": "2.", "explicacao": "S = a₁ ÷ (1 − q), com |q| < 1."}, {"id": 2000001121, "trilha": "enem", "materia": "mat", "assunto": "Geometria plana", "tipo": "pergunta", "frente": "Fórmula da área do triângulo.", "verso": "A = base × altura ÷ 2.", "explicacao": "Triângulo equilátero de lado l: A = l²√3 ÷ 4."}, {"id": 2000001122, "trilha": "enem", "materia": "mat", "assunto": "Geometria plana", "tipo": "pergunta", "frente": "Fórmulas do comprimento e da área do círculo.", "verso": "Comprimento: C = 2πr. Área: A = πr².", "explicacao": "Use π ≈ 3,14 se o enunciado não disser outro valor."}, {"id": 2000001123, "trilha": "enem", "materia": "mat", "assunto": "Geometria plana", "tipo": "pergunta", "frente": "Área do trapézio.", "verso": "A = (B + b) × h ÷ 2.", "explicacao": "B e b são as bases."}, {"id": 2000001124, "trilha": "enem", "materia": "mat", "assunto": "Geometria plana", "tipo": "pergunta", "frente": "O que diz o teorema de Pitágoras?", "verso": "Num triângulo retângulo, a² = b² + c² (hipotenusa ao quadrado é igual à soma dos quadrados dos catetos).", "explicacao": "Triângulo 3-4-5 é clássico."}, {"id": 2000001125, "trilha": "enem", "materia": "mat", "assunto": "Geometria plana", "tipo": "pergunta", "frente": "Quanto mede a soma dos ângulos internos de um triângulo?", "verso": "180°.", "explicacao": "De um polígono de n lados: (n − 2) × 180°."}, {"id": 2000001126, "trilha": "enem", "materia": "mat", "assunto": "Geometria plana", "tipo": "pergunta", "frente": "Se o lado de um quadrado dobra, o que acontece com a área?", "verso": "Fica 4 vezes maior.", "explicacao": "Área varia com o quadrado da razão de semelhança; volume, com o cubo."}, {"id": 2000001127, "trilha": "enem", "materia": "mat", "assunto": "Geometria plana", "tipo": "pares", "frente": "Seno x cosseno x tangente.", "verso": "Seno: cateto oposto ÷ hipotenusa. Cosseno: cateto adjacente ÷ hipotenusa. Tangente: cateto oposto ÷ cateto adjacente.", "explicacao": "Mnemônico: SOH-CAH-TOA."}, {"id": 2000001128, "trilha": "enem", "materia": "mat", "assunto": "Geometria plana", "tipo": "pergunta", "frente": "Quanto valem sen 30°, cos 60° e tg 45°?", "verso": "sen 30° = 1/2; cos 60° = 1/2; tg 45° = 1.", "explicacao": "sen 60° = cos 30° = √3/2."}, {"id": 2000001129, "trilha": "enem", "materia": "mat", "assunto": "Geometria espacial", "tipo": "pergunta", "frente": "Volume do cilindro.", "verso": "V = πr² × h.", "explicacao": "Área da base vezes a altura."}, {"id": 2000001130, "trilha": "enem", "materia": "mat", "assunto": "Geometria espacial", "tipo": "pergunta", "frente": "Volume do cone e da pirâmide.", "verso": "V = (área da base × altura) ÷ 3.", "explicacao": "Um terço do prisma ou cilindro de mesma base e altura."}, {"id": 2000001131, "trilha": "enem", "materia": "mat", "assunto": "Geometria espacial", "tipo": "pergunta", "frente": "Volume da esfera.", "verso": "V = (4/3)πr³.", "explicacao": "Área da superfície: 4πr²."}, {"id": 2000001132, "trilha": "enem", "materia": "mat", "assunto": "Geometria espacial", "tipo": "pergunta", "frente": "Volume do paralelepípedo.", "verso": "V = comprimento × largura × altura.", "explicacao": "Cubo de aresta a: V = a³."}, {"id": 2000001133, "trilha": "enem", "materia": "mat", "assunto": "Geometria espacial", "tipo": "pergunta", "frente": "O que diz a relação de Euler para poliedros convexos?", "verso": "V − A + F = 2 (vértices menos arestas mais faces).", "explicacao": "Cubo: 8 − 12 + 6 = 2."}, {"id": 2000001134, "trilha": "enem", "materia": "mat", "assunto": "Geometria espacial", "tipo": "pergunta", "frente": "Que figura forma a planificação da superfície lateral de um cilindro?", "verso": "Um retângulo, com largura igual ao comprimento da circunferência da base (2πr).", "explicacao": "Cone: setor circular."}, {"id": 2000001135, "trilha": "enem", "materia": "mat", "assunto": "Geometria analítica", "tipo": "pergunta", "frente": "Como calcular a distância entre dois pontos no plano?", "verso": "d = √[(x₂ − x₁)² + (y₂ − y₁)²].", "explicacao": "É Pitágoras no plano cartesiano."}, {"id": 2000001136, "trilha": "enem", "materia": "mat", "assunto": "Geometria analítica", "tipo": "pergunta", "frente": "Como achar o ponto médio de um segmento?", "verso": "Média das coordenadas: ((x₁ + x₂)/2, (y₁ + y₂)/2).", "explicacao": ""}, {"id": 2000001137, "trilha": "enem", "materia": "mat", "assunto": "Geometria analítica", "tipo": "pergunta", "frente": "Como se calcula o coeficiente angular de uma reta que passa por dois pontos?", "verso": "m = (y₂ − y₁) ÷ (x₂ − x₁).", "explicacao": "Retas paralelas têm o mesmo m."}, {"id": 2000001138, "trilha": "enem", "materia": "mat", "assunto": "Números", "tipo": "pergunta", "frente": "Como achar o MMC de dois números e quando ele é usado?", "verso": "Fatora e pega todos os fatores com os maiores expoentes. Usado quando eventos se repetem e se quer saber quando coincidem de novo.", "explicacao": "Ex.: ônibus que passam a cada 12 e 18 min coincidem a cada 36 min."}, {"id": 2000001139, "trilha": "enem", "materia": "mat", "assunto": "Números", "tipo": "pergunta", "frente": "Quando se usa o MDC em problemas?", "verso": "Para dividir em partes iguais do maior tamanho possível.", "explicacao": "Ex.: cortar fitas de 24 e 36 cm em pedaços iguais e máximos: 12 cm."}, {"id": 2000001140, "trilha": "enem", "materia": "mat", "assunto": "Números", "tipo": "pergunta", "frente": "Como escrever 0,000032 em notação científica?", "verso": "3,2 × 10⁻⁵.", "explicacao": "Mantissa entre 1 e 10."}, {"id": 2000001141, "trilha": "enem", "materia": "mat", "assunto": "Números", "tipo": "pergunta", "frente": "Quanto vale 2⁰ e 2⁻¹?", "verso": "2⁰ = 1 e 2⁻¹ = 1/2.", "explicacao": "Expoente negativo inverte a base."}, {"id": 2000001142, "trilha": "enem", "materia": "mat", "assunto": "Números", "tipo": "pergunta", "frente": "Qual a regra para multiplicar potências de mesma base?", "verso": "Conserva a base e soma os expoentes: aᵐ · aⁿ = aᵐ⁺ⁿ.", "explicacao": "Na divisão, subtrai os expoentes."}, {"id": 2000001143, "trilha": "enem", "materia": "mat", "assunto": "Números", "tipo": "pergunta", "frente": "Qual a fração geratriz de 0,333…?", "verso": "1/3.", "explicacao": "Dízima periódica simples: período sobre tantos 9 quantos algarismos tiver o período."}, {"id": 2000001144, "trilha": "enem", "materia": "mat", "assunto": "Matrizes", "tipo": "pergunta", "frente": "Qual condição permite multiplicar a matriz A (m × n) pela B (p × q)?", "verso": "n = p (colunas de A iguais às linhas de B). O resultado é m × q.", "explicacao": "A multiplicação de matrizes não é comutativa."}, {"id": 2000001145, "trilha": "enem", "materia": "mat", "assunto": "Matrizes", "tipo": "pergunta", "frente": "Como se calcula o determinante de uma matriz 2 × 2?", "verso": "Produto da diagonal principal menos o produto da diagonal secundária: ad − bc.", "explicacao": "Se det = 0, a matriz não tem inversa."}, {"id": 2000001146, "trilha": "enem", "materia": "mat", "assunto": "Sistemas", "tipo": "pergunta", "frente": "Quando um sistema linear 2 × 2 não tem solução?", "verso": "Quando as retas são paralelas e distintas (sistema impossível).", "explicacao": "Retas coincidentes: infinitas soluções (possível e indeterminado)."}, {"id": 2000001147, "trilha": "enem", "materia": "mat", "assunto": "Interpretação", "tipo": "pergunta", "frente": "No Enem, o que costuma ser a “pegadinha” de gráficos com eixo que não começa no zero?", "verso": "A variação parece maior do que é. Compare os valores, não o tamanho das barras.", "explicacao": "Leia sempre a escala dos eixos."}, {"id": 2000001148, "trilha": "enem", "materia": "mat", "assunto": "Interpretação", "tipo": "pergunta", "frente": "Como estimar rapidamente 19,8% de 502?", "verso": "Arredonde: 20% de 500 = 100.", "explicacao": "Estimativa ajuda a eliminar alternativas."}, {"id": 2000001149, "trilha": "enem", "materia": "mat", "assunto": "Interpretação", "tipo": "pergunta", "frente": "O que é taxa de variação de uma grandeza no tempo?", "verso": "Quanto ela muda por unidade de tempo: (valor final − inicial) ÷ intervalo de tempo.", "explicacao": "Num gráfico de reta, é a inclinação."}, {"id": 2000001150, "trilha": "enem", "materia": "fis", "assunto": "Cinemática", "tipo": "pergunta", "frente": "Fórmula da posição no movimento uniforme (MU).", "verso": "S = S₀ + v·t.", "explicacao": "Velocidade constante, aceleração nula."}, {"id": 2000001151, "trilha": "enem", "materia": "fis", "assunto": "Cinemática", "tipo": "pergunta", "frente": "Fórmulas do movimento uniformemente variado (MUV).", "verso": "v = v₀ + a·t; S = S₀ + v₀·t + a·t²/2; v² = v₀² + 2·a·ΔS (Torricelli).", "explicacao": "Torricelli não usa o tempo."}, {"id": 2000001152, "trilha": "enem", "materia": "fis", "assunto": "Cinemática", "tipo": "pergunta", "frente": "Num gráfico velocidade × tempo, o que representa a área sob a curva?", "verso": "O deslocamento.", "explicacao": "A inclinação desse gráfico é a aceleração."}, {"id": 2000001153, "trilha": "enem", "materia": "fis", "assunto": "Cinemática", "tipo": "pergunta", "frente": "Num gráfico posição × tempo, o que representa a inclinação?", "verso": "A velocidade.", "explicacao": "Reta: MU. Parábola: MUV."}, {"id": 2000001154, "trilha": "enem", "materia": "fis", "assunto": "Cinemática", "tipo": "certo_errado", "frente": "Certo ou errado? Sem resistência do ar, um corpo pesado cai mais rápido que um leve.", "verso": "Errado. Na queda livre, todos caem com a mesma aceleração (g ≈ 10 m/s²).", "explicacao": "Galileu."}, {"id": 2000001155, "trilha": "enem", "materia": "fis", "assunto": "Cinemática", "tipo": "pergunta", "frente": "No lançamento oblíquo sem resistência do ar, o que acontece com a velocidade horizontal?", "verso": "Permanece constante durante todo o movimento.", "explicacao": "Na vertical, há MUV com aceleração g."}, {"id": 2000001156, "trilha": "enem", "materia": "fis", "assunto": "Cinemática", "tipo": "pergunta", "frente": "No movimento circular uniforme, existe aceleração?", "verso": "Sim, a centrípeta (a = v²/R), que muda só a direção da velocidade.", "explicacao": "O módulo da velocidade fica constante."}, {"id": 2000001157, "trilha": "enem", "materia": "fis", "assunto": "Cinemática", "tipo": "pares", "frente": "Período x frequência.", "verso": "Período (T): tempo de uma volta, em segundos. Frequência (f): voltas por segundo, em hertz. f = 1/T.", "explicacao": "Em engrenagens ligadas por correia, a velocidade linear é igual."}, {"id": 2000001158, "trilha": "enem", "materia": "fis", "assunto": "Dinâmica", "tipo": "pergunta", "frente": "O que diz a 1ª lei de Newton (inércia)?", "verso": "Um corpo tende a manter seu estado de repouso ou de movimento retilíneo uniforme se a força resultante for nula.", "explicacao": "Por isso usamos cinto de segurança."}, {"id": 2000001159, "trilha": "enem", "materia": "fis", "assunto": "Dinâmica", "tipo": "lacuna", "frente": "2ª lei de Newton: força resultante = ___ × aceleração.", "verso": "Massa (F = m·a).", "explicacao": "Unidade: newton (N) = kg·m/s²."}, {"id": 2000001160, "trilha": "enem", "materia": "fis", "assunto": "Dinâmica", "tipo": "pergunta", "frente": "O que diz a 3ª lei de Newton?", "verso": "Toda ação tem uma reação de mesma intensidade, mesma direção e sentido oposto, aplicada em corpos diferentes.", "explicacao": "Por isso ação e reação não se anulam."}, {"id": 2000001161, "trilha": "enem", "materia": "fis", "assunto": "Dinâmica", "tipo": "pares", "frente": "Massa x peso.", "verso": "Massa: quantidade de matéria, em kg, não muda com o lugar. Peso: força gravitacional, P = m·g, em newtons, muda com a gravidade.", "explicacao": "Na Lua, a massa é a mesma e o peso é cerca de 1/6."}, {"id": 2000001162, "trilha": "enem", "materia": "fis", "assunto": "Dinâmica", "tipo": "pergunta", "frente": "Do que depende a força de atrito?", "verso": "Do coeficiente de atrito e da força normal: Fat = μ·N.", "explicacao": "Não depende da área de contato (no modelo básico)."}, {"id": 2000001163, "trilha": "enem", "materia": "fis", "assunto": "Dinâmica", "tipo": "pares", "frente": "Atrito estático x dinâmico.", "verso": "Estático: atua enquanto o corpo não desliza; tem valor máximo maior. Dinâmico (cinético): atua com o corpo em movimento; é constante e menor.", "explicacao": "Freio ABS evita o travamento para aproveitar o atrito estático."}, {"id": 2000001164, "trilha": "enem", "materia": "fis", "assunto": "Dinâmica", "tipo": "pergunta", "frente": "O que diz a lei de Hooke?", "verso": "A força elástica de uma mola é proporcional à deformação: F = k·x.", "explicacao": "k é a constante elástica."}, {"id": 2000001165, "trilha": "enem", "materia": "fis", "assunto": "Energia", "tipo": "pergunta", "frente": "Fórmula da energia cinética.", "verso": "Ec = m·v²/2.", "explicacao": "Dobrar a velocidade quadruplica a energia cinética."}, {"id": 2000001166, "trilha": "enem", "materia": "fis", "assunto": "Energia", "tipo": "pergunta", "frente": "Fórmula da energia potencial gravitacional.", "verso": "Ep = m·g·h.", "explicacao": "Depende da altura em relação a um referencial."}, {"id": 2000001167, "trilha": "enem", "materia": "fis", "assunto": "Energia", "tipo": "pergunta", "frente": "Num sistema sem atrito, o que acontece com a energia mecânica?", "verso": "Ela se conserva: Ec + Ep = constante.", "explicacao": "Com atrito, parte vira energia térmica."}, {"id": 2000001168, "trilha": "enem", "materia": "fis", "assunto": "Energia", "tipo": "pergunta", "frente": "Como se calcula a potência?", "verso": "P = trabalho (ou energia) ÷ tempo. Unidade: watt (W) = J/s.", "explicacao": "1 kWh = 3,6 × 10⁶ J."}, {"id": 2000001169, "trilha": "enem", "materia": "fis", "assunto": "Energia", "tipo": "pergunta", "frente": "Como calcular o consumo de um chuveiro de 5.000 W ligado 30 min por dia durante 30 dias?", "verso": "5 kW × 0,5 h × 30 = 75 kWh.", "explicacao": "Energia = potência × tempo."}, {"id": 2000001170, "trilha": "enem", "materia": "fis", "assunto": "Energia", "tipo": "pergunta", "frente": "O que é rendimento de uma máquina?", "verso": "A razão entre a energia útil e a energia total recebida: η = útil ÷ total.", "explicacao": "Sempre menor que 100% em máquinas reais."}, {"id": 2000001171, "trilha": "enem", "materia": "fis", "assunto": "Energia", "tipo": "pares", "frente": "Usina hidrelétrica x termelétrica x eólica: transformação de energia.", "verso": "Hidrelétrica: potencial gravitacional da água → cinética → elétrica. Termelétrica: química do combustível → térmica → cinética → elétrica. Eólica: cinética do vento → elétrica.", "explicacao": "Nuclear: energia nuclear → térmica → elétrica."}, {"id": 2000001172, "trilha": "enem", "materia": "fis", "assunto": "Energia", "tipo": "pergunta", "frente": "Como funciona uma usina nuclear?", "verso": "A fissão do urânio libera calor que aquece água; o vapor gira turbinas ligadas a geradores.", "explicacao": "Não emite CO₂ na geração, mas gera rejeito radioativo."}, {"id": 2000001173, "trilha": "enem", "materia": "fis", "assunto": "Impulso", "tipo": "pergunta", "frente": "O que diz a conservação da quantidade de movimento?", "verso": "Num sistema isolado, a quantidade de movimento total (Q = m·v) antes é igual à de depois.", "explicacao": "Base do recuo da arma e da propulsão de foguetes."}, {"id": 2000001174, "trilha": "enem", "materia": "fis", "assunto": "Impulso", "tipo": "pergunta", "frente": "Por que o airbag reduz lesões?", "verso": "Aumenta o tempo de colisão, o que diminui a força média sobre o corpo para a mesma variação de movimento.", "explicacao": "Impulso: F·Δt = ΔQ."}, {"id": 2000001175, "trilha": "enem", "materia": "fis", "assunto": "Hidrostática", "tipo": "pergunta", "frente": "Fórmula da pressão.", "verso": "P = F ÷ A.", "explicacao": "Faca afiada: área pequena, pressão grande."}, {"id": 2000001176, "trilha": "enem", "materia": "fis", "assunto": "Hidrostática", "tipo": "pergunta", "frente": "O que diz o teorema de Stevin?", "verso": "A pressão num líquido aumenta com a profundidade: P = P₀ + d·g·h.", "explicacao": "A cada 10 m de água, cerca de 1 atm a mais."}, {"id": 2000001177, "trilha": "enem", "materia": "fis", "assunto": "Hidrostática", "tipo": "pergunta", "frente": "O que diz o princípio de Pascal?", "verso": "Um acréscimo de pressão num líquido em equilíbrio se transmite integralmente a todos os pontos.", "explicacao": "Base do macaco e do freio hidráulico."}, {"id": 2000001178, "trilha": "enem", "materia": "fis", "assunto": "Hidrostática", "tipo": "pergunta", "frente": "O que diz o princípio de Arquimedes?", "verso": "Todo corpo imerso num fluido recebe um empuxo vertical para cima igual ao peso do fluido deslocado: E = d·V·g.", "explicacao": "Corpo flutua se for menos denso que o líquido."}, {"id": 2000001179, "trilha": "enem", "materia": "fis", "assunto": "Termologia", "tipo": "pergunta", "frente": "Como converter graus Celsius em Kelvin?", "verso": "K = °C + 273.", "explicacao": "0 K é o zero absoluto."}, {"id": 2000001180, "trilha": "enem", "materia": "fis", "assunto": "Termologia", "tipo": "pergunta", "frente": "Fórmula da conversão entre Celsius e Fahrenheit.", "verso": "°C/5 = (°F − 32)/9.", "explicacao": "100 °C = 212 °F."}, {"id": 2000001181, "trilha": "enem", "materia": "fis", "assunto": "Termologia", "tipo": "pares", "frente": "Calor sensível x calor latente.", "verso": "Sensível: muda a temperatura (Q = m·c·ΔT). Latente: muda o estado físico, com temperatura constante (Q = m·L).", "explicacao": "Durante a fervura, a água fica a 100 °C (ao nível do mar)."}, {"id": 2000001182, "trilha": "enem", "materia": "fis", "assunto": "Termologia", "tipo": "pares", "frente": "Condução x convecção x irradiação.", "verso": "Condução: por contato, de partícula a partícula (sólidos). Convecção: por correntes no fluido (geladeira, ar-condicionado no alto). Irradiação: por ondas eletromagnéticas, inclusive no vácuo (Sol).", "explicacao": "Garrafa térmica dificulta as três."}, {"id": 2000001183, "trilha": "enem", "materia": "fis", "assunto": "Termologia", "tipo": "pergunta", "frente": "Por que o congelador fica na parte de cima da geladeira?", "verso": "O ar frio, mais denso, desce; o quente sobe, formando correntes de convecção.", "explicacao": "O ar-condicionado também deve ficar no alto."}, {"id": 2000001184, "trilha": "enem", "materia": "fis", "assunto": "Termologia", "tipo": "pergunta", "frente": "O que é calor específico?", "verso": "A quantidade de calor para elevar em 1 °C a temperatura de 1 g de uma substância.", "explicacao": "A água tem calor específico alto: esquenta e esfria devagar."}, {"id": 2000001185, "trilha": "enem", "materia": "fis", "assunto": "Termologia", "tipo": "pergunta", "frente": "Por que a panela de pressão cozinha mais rápido?", "verso": "A pressão maior eleva o ponto de ebulição da água acima de 100 °C.", "explicacao": "Em locais altos, a água ferve abaixo de 100 °C."}, {"id": 2000001186, "trilha": "enem", "materia": "fis", "assunto": "Termodinâmica", "tipo": "pergunta", "frente": "O que diz a 1ª lei da Termodinâmica?", "verso": "Q = τ + ΔU: o calor recebido vira trabalho e variação de energia interna.", "explicacao": "Conservação de energia."}, {"id": 2000001187, "trilha": "enem", "materia": "fis", "assunto": "Termodinâmica", "tipo": "pergunta", "frente": "O que diz a 2ª lei da Termodinâmica?", "verso": "O calor flui espontaneamente do corpo quente para o frio, e nenhuma máquina térmica converte todo o calor em trabalho.", "explicacao": "Rendimento de Carnot: 1 − Tfria/Tquente (em kelvin)."}, {"id": 2000001188, "trilha": "enem", "materia": "fis", "assunto": "Ondas", "tipo": "pergunta", "frente": "Equação fundamental da ondulatória.", "verso": "v = λ·f (velocidade = comprimento de onda × frequência).", "explicacao": "Na refração, a frequência não muda."}, {"id": 2000001189, "trilha": "enem", "materia": "fis", "assunto": "Ondas", "tipo": "pares", "frente": "Ondas mecânicas x eletromagnéticas.", "verso": "Mecânicas: precisam de meio material (som, ondas do mar). Eletromagnéticas: propagam-se também no vácuo (luz, rádio, raio X).", "explicacao": "No vácuo, a luz viaja a 3 × 10⁸ m/s."}, {"id": 2000001190, "trilha": "enem", "materia": "fis", "assunto": "Ondas", "tipo": "pares", "frente": "Altura x intensidade x timbre do som.", "verso": "Altura: depende da frequência (agudo ou grave). Intensidade: depende da amplitude (forte ou fraco). Timbre: forma da onda, que diferencia instrumentos.", "explicacao": "Popularmente “volume alto” é intensidade, não altura."}, {"id": 2000001191, "trilha": "enem", "materia": "fis", "assunto": "Ondas", "tipo": "pergunta", "frente": "O que é o efeito Doppler?", "verso": "Variação da frequência percebida quando fonte e observador se aproximam (som mais agudo) ou se afastam (mais grave).", "explicacao": "Usado em radares e ultrassom."}, {"id": 2000001192, "trilha": "enem", "materia": "fis", "assunto": "Ondas", "tipo": "pergunta", "frente": "O que é ressonância?", "verso": "Quando um corpo é excitado com sua frequência natural de vibração, a amplitude aumenta muito.", "explicacao": "Exemplo: taça que quebra com a voz; sintonia de rádio."}, {"id": 2000001193, "trilha": "enem", "materia": "fis", "assunto": "Ondas", "tipo": "pergunta", "frente": "Por que se usa ultrassom em exames médicos?", "verso": "Porque as ondas sonoras de alta frequência refletem nos tecidos e formam imagens, sem radiação ionizante.", "explicacao": "Ecolocalização dos morcegos usa o mesmo princípio."}, {"id": 2000001194, "trilha": "enem", "materia": "fis", "assunto": "Óptica", "tipo": "pergunta", "frente": "O que diz a lei da reflexão?", "verso": "O ângulo de incidência é igual ao ângulo de reflexão.", "explicacao": "Ambos medidos em relação à normal."}, {"id": 2000001195, "trilha": "enem", "materia": "fis", "assunto": "Óptica", "tipo": "pergunta", "frente": "O que é refração da luz?", "verso": "A mudança de velocidade (e geralmente de direção) da luz ao passar de um meio para outro.", "explicacao": "Por isso o lápis parece quebrado no copo d'água."}, {"id": 2000001196, "trilha": "enem", "materia": "fis", "assunto": "Óptica", "tipo": "pergunta", "frente": "Por que o céu é azul?", "verso": "A luz azul é mais espalhada pelas moléculas do ar que as outras cores.", "explicacao": "Espalhamento de Rayleigh."}, {"id": 2000001197, "trilha": "enem", "materia": "fis", "assunto": "Óptica", "tipo": "pergunta", "frente": "O que é a dispersão da luz?", "verso": "A separação da luz branca nas cores do espectro, porque cada cor refrata de modo diferente.", "explicacao": "Prisma e arco-íris."}, {"id": 2000001198, "trilha": "enem", "materia": "fis", "assunto": "Óptica", "tipo": "pares", "frente": "Miopia x hipermetropia: lente de correção.", "verso": "Miopia: imagem se forma antes da retina, dificuldade de ver de longe; corrige com lente divergente. Hipermetropia: imagem depois da retina, dificuldade de ver de perto; lente convergente.", "explicacao": "Presbiopia (vista cansada) também usa lente convergente."}, {"id": 2000001199, "trilha": "enem", "materia": "fis", "assunto": "Óptica", "tipo": "pergunta", "frente": "Por que um objeto parece vermelho sob luz branca?", "verso": "Ele reflete a luz vermelha e absorve as demais cores.", "explicacao": "Sob luz azul, um objeto vermelho parece escuro."}, {"id": 2000001200, "trilha": "enem", "materia": "fis", "assunto": "Eletricidade", "tipo": "lacuna", "frente": "Lei de Ohm: U = ___ × i.", "verso": "R (resistência). U em volts, R em ohms, i em ampères.", "explicacao": "1ª lei de Ohm."}, {"id": 2000001201, "trilha": "enem", "materia": "fis", "assunto": "Eletricidade", "tipo": "pergunta", "frente": "Fórmulas da potência elétrica.", "verso": "P = U·i = R·i² = U²/R.", "explicacao": "Em watts."}, {"id": 2000001202, "trilha": "enem", "materia": "fis", "assunto": "Eletricidade", "tipo": "pares", "frente": "Resistores em série x em paralelo.", "verso": "Série: mesma corrente, resistências se somam. Paralelo: mesma tensão, o inverso da resistência equivalente é a soma dos inversos.", "explicacao": "As tomadas de uma casa estão em paralelo."}, {"id": 2000001203, "trilha": "enem", "materia": "fis", "assunto": "Eletricidade", "tipo": "pergunta", "frente": "Por que o chuveiro na posição “inverno” esquenta mais?", "verso": "Usa uma resistência menor; com a mesma tensão, a potência (U²/R) aumenta.", "explicacao": "Pergunta clássica do Enem."}, {"id": 2000001204, "trilha": "enem", "materia": "fis", "assunto": "Eletricidade", "tipo": "pergunta", "frente": "Para que serve o disjuntor (ou fusível)?", "verso": "Interromper o circuito quando a corrente passa do limite, evitando superaquecimento e incêndio.", "explicacao": "Fica em série com o circuito protegido."}, {"id": 2000001205, "trilha": "enem", "materia": "fis", "assunto": "Eletricidade", "tipo": "pergunta", "frente": "Para que serve o fio terra?", "verso": "Desviar para o solo cargas indesejadas, protegendo as pessoas de choques.", "explicacao": "Importante em chuveiros e máquinas de lavar."}, {"id": 2000001206, "trilha": "enem", "materia": "fis", "assunto": "Eletricidade", "tipo": "pergunta", "frente": "O que é a indução eletromagnética?", "verso": "A geração de corrente elétrica pela variação do campo magnético num circuito (lei de Faraday).", "explicacao": "Princípio dos geradores de usinas e dos transformadores."}, {"id": 2000001207, "trilha": "enem", "materia": "fis", "assunto": "Eletricidade", "tipo": "pergunta", "frente": "Por que o transformador só funciona com corrente alternada?", "verso": "Porque precisa de campo magnético variável para induzir corrente no outro enrolamento.", "explicacao": "Razão de tensões = razão do número de espiras."}, {"id": 2000001208, "trilha": "enem", "materia": "fis", "assunto": "Eletrostática", "tipo": "pergunta", "frente": "Como funciona o para-raios?", "verso": "Oferece um caminho preferencial para a descarga elétrica até o solo, pelo poder das pontas.", "explicacao": "Cargas se concentram nas pontas dos condutores."}, {"id": 2000001209, "trilha": "enem", "materia": "fis", "assunto": "Eletrostática", "tipo": "pergunta", "frente": "Por que dentro de um carro estamos protegidos de um raio?", "verso": "A carroceria metálica funciona como gaiola de Faraday: as cargas ficam na superfície externa e o campo interno é nulo.", "explicacao": "Não é por causa dos pneus de borracha."}, {"id": 2000001210, "trilha": "enem", "materia": "qui", "assunto": "Matéria", "tipo": "pares", "frente": "Fenômeno físico x químico.", "verso": "Físico: não altera a natureza da substância (derreter gelo, quebrar vidro). Químico: forma novas substâncias (queima, ferrugem, digestão).", "explicacao": "Sinais de reação: gás, mudança de cor, precipitado, calor."}, {"id": 2000001211, "trilha": "enem", "materia": "qui", "assunto": "Matéria", "tipo": "pares", "frente": "Substância pura x mistura.", "verso": "Pura: composição fixa e ponto de fusão e ebulição constantes. Mistura: composição variável; a temperatura varia durante a mudança de estado.", "explicacao": "Exceções: misturas eutéticas e azeotrópicas."}, {"id": 2000001212, "trilha": "enem", "materia": "qui", "assunto": "Matéria", "tipo": "pares", "frente": "Mistura homogênea x heterogênea.", "verso": "Homogênea: uma só fase (água com sal dissolvido, ar). Heterogênea: duas ou mais fases (água e óleo, granito).", "explicacao": "Fase é cada porção visualmente uniforme."}, {"id": 2000001213, "trilha": "enem", "materia": "qui", "assunto": "Separação de misturas", "tipo": "pergunta", "frente": "Que método separa sal da água do mar para obter o sal?", "verso": "Evaporação (nas salinas).", "explicacao": "Para obter a água pura, destilação simples."}, {"id": 2000001214, "trilha": "enem", "materia": "qui", "assunto": "Separação de misturas", "tipo": "pergunta", "frente": "Que método separa líquidos miscíveis com pontos de ebulição diferentes, como álcool e água?", "verso": "Destilação fracionada.", "explicacao": "Também usada no refino do petróleo."}, {"id": 2000001215, "trilha": "enem", "materia": "qui", "assunto": "Separação de misturas", "tipo": "pergunta", "frente": "Que método separa água e óleo?", "verso": "Decantação, com funil de separação (de bromo).", "explicacao": "Líquidos imiscíveis."}, {"id": 2000001216, "trilha": "enem", "materia": "qui", "assunto": "Separação de misturas", "tipo": "pergunta", "frente": "O que é filtração e cite um exemplo cotidiano.", "verso": "Separação de sólido e líquido (ou gás) por um filtro que retém o sólido. Ex.: coar o café.", "explicacao": "Aspirador de pó também filtra (sólido e gás)."}, {"id": 2000001217, "trilha": "enem", "materia": "qui", "assunto": "Separação de misturas", "tipo": "pergunta", "frente": "Quais as etapas do tratamento de água?", "verso": "Coagulação/floculação, decantação, filtração, desinfecção (cloração) e fluoretação.", "explicacao": "O sulfato de alumínio ajuda a formar flocos."}, {"id": 2000001218, "trilha": "enem", "materia": "qui", "assunto": "Atomística", "tipo": "pergunta", "frente": "O que são isótopos?", "verso": "Átomos do mesmo elemento (mesmo número de prótons) com número de massa diferente (nêutrons diferentes).", "explicacao": "Ex.: carbono-12 e carbono-14."}, {"id": 2000001219, "trilha": "enem", "materia": "qui", "assunto": "Atomística", "tipo": "pares", "frente": "Número atômico x número de massa.", "verso": "Número atômico (Z): prótons. Número de massa (A): prótons + nêutrons.", "explicacao": "Num átomo neutro, elétrons = prótons."}, {"id": 2000001220, "trilha": "enem", "materia": "qui", "assunto": "Atomística", "tipo": "pares", "frente": "Cátion x ânion.", "verso": "Cátion: íon positivo, perdeu elétrons (Na⁺). Ânion: íon negativo, ganhou elétrons (Cl⁻).", "explicacao": "Metais tendem a formar cátions."}, {"id": 2000001221, "trilha": "enem", "materia": "qui", "assunto": "Tabela periódica", "tipo": "pergunta", "frente": "Como a tabela periódica é organizada?", "verso": "Em ordem crescente de número atômico: períodos (linhas) indicam camadas eletrônicas; famílias (colunas) reúnem elementos com propriedades parecidas.", "explicacao": "18 famílias."}, {"id": 2000001222, "trilha": "enem", "materia": "qui", "assunto": "Tabela periódica", "tipo": "pergunta", "frente": "Quais elementos formam a família dos gases nobres e por que são pouco reativos?", "verso": "He, Ne, Ar, Kr, Xe, Rn; têm a camada de valência completa.", "explicacao": "Família 18."}, {"id": 2000001223, "trilha": "enem", "materia": "qui", "assunto": "Tabela periódica", "tipo": "pergunta", "frente": "Como varia a eletronegatividade na tabela periódica?", "verso": "Aumenta da esquerda para a direita e de baixo para cima. O flúor é o mais eletronegativo.", "explicacao": "Gases nobres geralmente não entram na comparação."}, {"id": 2000001224, "trilha": "enem", "materia": "qui", "assunto": "Ligações", "tipo": "pares", "frente": "Ligação iônica x covalente x metálica.", "verso": "Iônica: metal + ametal, transferência de elétrons (NaCl). Covalente: ametal + ametal, compartilhamento (H₂O). Metálica: entre metais, “mar de elétrons” livres.", "explicacao": "Compostos iônicos conduzem eletricidade fundidos ou em solução."}, {"id": 2000001225, "trilha": "enem", "materia": "qui", "assunto": "Ligações", "tipo": "pergunta", "frente": "Por que a água tem ponto de ebulição alto para uma molécula tão pequena?", "verso": "Por causa das ligações de hidrogênio entre as moléculas.", "explicacao": "Ligações de hidrogênio: H ligado a F, O ou N."}, {"id": 2000001226, "trilha": "enem", "materia": "qui", "assunto": "Ligações", "tipo": "pergunta", "frente": "Por que óleo e água não se misturam?", "verso": "Água é polar e o óleo é apolar; “semelhante dissolve semelhante”.", "explicacao": "O sabão tem parte polar e parte apolar e une os dois."}, {"id": 2000001227, "trilha": "enem", "materia": "qui", "assunto": "Ligações", "tipo": "pergunta", "frente": "Como o sabão remove a gordura?", "verso": "A cauda apolar se liga à gordura e a cabeça polar à água, formando micelas que são levadas no enxágue.", "explicacao": "O sabão é um sal de ácido graxo."}, {"id": 2000001228, "trilha": "enem", "materia": "qui", "assunto": "Funções inorgânicas", "tipo": "pares", "frente": "Ácido x base (Arrhenius).", "verso": "Ácido: em água libera H⁺ (HCl). Base: em água libera OH⁻ (NaOH).", "explicacao": "Ácido + base → sal + água (neutralização)."}, {"id": 2000001229, "trilha": "enem", "materia": "qui", "assunto": "Funções inorgânicas", "tipo": "pergunta", "frente": "O que indica a escala de pH?", "verso": "A acidez: pH < 7 ácido, pH = 7 neutro, pH > 7 básico (a 25 °C).", "explicacao": "Cada unidade de pH equivale a 10 vezes na concentração de H⁺."}, {"id": 2000001230, "trilha": "enem", "materia": "qui", "assunto": "Funções inorgânicas", "tipo": "pergunta", "frente": "O que causa a chuva ácida?", "verso": "Óxidos de enxofre (SO₂) e de nitrogênio (NOx), de combustíveis fósseis e indústrias, que reagem com a água da chuva formando ácidos.", "explicacao": "Corrói monumentos e acidifica solos e lagos."}, {"id": 2000001231, "trilha": "enem", "materia": "qui", "assunto": "Funções inorgânicas", "tipo": "pergunta", "frente": "Por que se usa calcário (calagem) em solos ácidos?", "verso": "O carbonato de cálcio neutraliza a acidez do solo.", "explicacao": "Comum no cerrado."}, {"id": 2000001232, "trilha": "enem", "materia": "qui", "assunto": "Funções inorgânicas", "tipo": "pergunta", "frente": "Por que um antiácido alivia a azia?", "verso": "Contém uma base fraca (como hidróxido de magnésio ou bicarbonato de sódio) que neutraliza o excesso de ácido no estômago.", "explicacao": "O suco gástrico contém HCl."}, {"id": 2000001233, "trilha": "enem", "materia": "qui", "assunto": "Estequiometria", "tipo": "pergunta", "frente": "Quantas partículas há em 1 mol?", "verso": "Cerca de 6,0 × 10²³ (constante de Avogadro).", "explicacao": "1 mol de gás nas CNTP ocupa cerca de 22,4 L."}, {"id": 2000001234, "trilha": "enem", "materia": "qui", "assunto": "Estequiometria", "tipo": "pergunta", "frente": "O que diz a lei de Lavoisier?", "verso": "Num sistema fechado, a massa total dos reagentes é igual à dos produtos.", "explicacao": "“Na natureza nada se cria, nada se perde, tudo se transforma”."}, {"id": 2000001235, "trilha": "enem", "materia": "qui", "assunto": "Estequiometria", "tipo": "pergunta", "frente": "Como resolver um problema de estequiometria?", "verso": "Balancear a equação, usar a proporção em mols entre as substâncias e converter para massa, volume ou partículas com regra de três.", "explicacao": "Atenção ao reagente limitante e ao rendimento."}, {"id": 2000001236, "trilha": "enem", "materia": "qui", "assunto": "Soluções", "tipo": "pergunta", "frente": "Fórmula da concentração comum.", "verso": "C = massa do soluto (g) ÷ volume da solução (L).", "explicacao": "Unidade: g/L."}, {"id": 2000001237, "trilha": "enem", "materia": "qui", "assunto": "Soluções", "tipo": "pergunta", "frente": "O que acontece com a concentração numa diluição?", "verso": "Diminui, mas a quantidade de soluto não muda: C₁·V₁ = C₂·V₂.", "explicacao": "Diluir = acrescentar solvente."}, {"id": 2000001238, "trilha": "enem", "materia": "qui", "assunto": "Soluções", "tipo": "pergunta", "frente": "O que significa “ppm”?", "verso": "Partes por milhão: 1 ppm = 1 mg de soluto por kg (ou cerca de 1 mg por litro de água).", "explicacao": "Usado para poluentes e flúor na água."}, {"id": 2000001239, "trilha": "enem", "materia": "qui", "assunto": "Propriedades coligativas", "tipo": "pergunta", "frente": "Por que se joga sal nas ruas com neve?", "verso": "O soluto diminui a temperatura de congelamento da água (crioscopia).", "explicacao": "Propriedade coligativa: depende da quantidade de partículas, não da natureza."}, {"id": 2000001240, "trilha": "enem", "materia": "qui", "assunto": "Propriedades coligativas", "tipo": "pergunta", "frente": "O que é osmose?", "verso": "Passagem do solvente por membrana semipermeável, do meio menos concentrado para o mais concentrado.", "explicacao": "Por isso a salada murcha com sal."}, {"id": 2000001241, "trilha": "enem", "materia": "qui", "assunto": "Termoquímica", "tipo": "pares", "frente": "Reação exotérmica x endotérmica.", "verso": "Exotérmica: libera calor (ΔH < 0), como a combustão. Endotérmica: absorve calor (ΔH > 0), como a fotossíntese e o derretimento do gelo.", "explicacao": "Bolsa de gelo instantâneo usa processo endotérmico."}, {"id": 2000001242, "trilha": "enem", "materia": "qui", "assunto": "Cinética", "tipo": "pergunta", "frente": "Quais fatores aumentam a velocidade de uma reação?", "verso": "Temperatura maior, concentração maior, maior superfície de contato e catalisador.", "explicacao": "Comprimido triturado reage mais rápido."}, {"id": 2000001243, "trilha": "enem", "materia": "qui", "assunto": "Cinética", "tipo": "pergunta", "frente": "Como age um catalisador?", "verso": "Diminui a energia de ativação, acelerando a reação sem ser consumido.", "explicacao": "Enzimas são catalisadores biológicos; catalisador automotivo reduz poluentes."}, {"id": 2000001244, "trilha": "enem", "materia": "qui", "assunto": "Equilíbrio", "tipo": "pergunta", "frente": "O que diz o princípio de Le Chatelier?", "verso": "Quando um sistema em equilíbrio sofre uma perturbação, ele se desloca no sentido de reduzi-la.", "explicacao": "Ex.: aumentar a pressão desloca para o lado com menos mols de gás."}, {"id": 2000001245, "trilha": "enem", "materia": "qui", "assunto": "Eletroquímica", "tipo": "pares", "frente": "Oxidação x redução.", "verso": "Oxidação: perda de elétrons (o nox aumenta). Redução: ganho de elétrons (o nox diminui).", "explicacao": "Quem se oxida é o agente redutor."}, {"id": 2000001246, "trilha": "enem", "materia": "qui", "assunto": "Eletroquímica", "tipo": "pares", "frente": "Pilha x eletrólise.", "verso": "Pilha: reação espontânea gera corrente elétrica. Eletrólise: corrente elétrica força uma reação não espontânea.", "explicacao": "Na pilha, o ânodo é o polo negativo; na eletrólise, o positivo."}, {"id": 2000001247, "trilha": "enem", "materia": "qui", "assunto": "Eletroquímica", "tipo": "pergunta", "frente": "O que é metal de sacrifício?", "verso": "Metal mais reativo (como magnésio ou zinco) que se oxida no lugar de outro, protegendo-o da corrosão.", "explicacao": "Usado em cascos de navios e tubulações."}, {"id": 2000001248, "trilha": "enem", "materia": "qui", "assunto": "Eletroquímica", "tipo": "pergunta", "frente": "O que é galvanização?", "verso": "Revestir o ferro com zinco para protegê-lo da corrosão.", "explicacao": "Ferro galvanizado em calhas e pregos."}, {"id": 2000001249, "trilha": "enem", "materia": "qui", "assunto": "Radioatividade", "tipo": "pares", "frente": "Partículas alfa x beta x radiação gama.", "verso": "Alfa: 2 prótons e 2 nêutrons, pouco penetrante (papel barra). Beta: elétron emitido pelo núcleo, penetração média. Gama: onda eletromagnética, muito penetrante (chumbo e concreto barram).", "explicacao": "Emissão alfa diminui a massa em 4 e o número atômico em 2."}, {"id": 2000001250, "trilha": "enem", "materia": "qui", "assunto": "Radioatividade", "tipo": "pergunta", "frente": "O que é meia-vida?", "verso": "O tempo para metade dos núcleos radioativos de uma amostra se desintegrar.", "explicacao": "Carbono-14 (cerca de 5.730 anos) é usado em datação."}, {"id": 2000001251, "trilha": "enem", "materia": "qui", "assunto": "Radioatividade", "tipo": "pares", "frente": "Fissão x fusão nuclear.", "verso": "Fissão: núcleo pesado se divide (urânio em usinas e na bomba atômica). Fusão: núcleos leves se unem (hidrogênio no Sol).", "explicacao": "A fusão libera mais energia por massa."}, {"id": 2000001252, "trilha": "enem", "materia": "qui", "assunto": "Orgânica", "tipo": "pergunta", "frente": "Quais as características do carbono que explicam tantos compostos orgânicos?", "verso": "É tetravalente e forma cadeias longas, com ligações simples, duplas ou triplas.", "explicacao": ""}, {"id": 2000001253, "trilha": "enem", "materia": "qui", "assunto": "Orgânica", "tipo": "pergunta", "frente": "Que grupo funcional caracteriza os álcoois?", "verso": "Hidroxila (−OH) ligada a carbono saturado.", "explicacao": "Etanol: CH₃CH₂OH."}, {"id": 2000001254, "trilha": "enem", "materia": "qui", "assunto": "Orgânica", "tipo": "pergunta", "frente": "Que grupo funcional caracteriza os ácidos carboxílicos?", "verso": "Carboxila (−COOH).", "explicacao": "Ácido acético, do vinagre."}, {"id": 2000001255, "trilha": "enem", "materia": "qui", "assunto": "Orgânica", "tipo": "pares", "frente": "Éster x éter.", "verso": "Éster: R−COO−R', aromas e gorduras; vem de ácido + álcool (esterificação). Éter: R−O−R', usado como solvente e antigo anestésico.", "explicacao": "Biodiesel é uma mistura de ésteres."}, {"id": 2000001256, "trilha": "enem", "materia": "qui", "assunto": "Orgânica", "tipo": "pergunta", "frente": "Que grupos funcionais compõem um aminoácido?", "verso": "Grupo amina (−NH₂) e carboxila (−COOH).", "explicacao": "Aminoácidos se ligam por ligações peptídicas formando proteínas."}, {"id": 2000001257, "trilha": "enem", "materia": "qui", "assunto": "Orgânica", "tipo": "pergunta", "frente": "O que são hidrocarbonetos?", "verso": "Compostos formados só por carbono e hidrogênio.", "explicacao": "Metano, butano (gás de cozinha), octano (gasolina)."}, {"id": 2000001258, "trilha": "enem", "materia": "qui", "assunto": "Orgânica", "tipo": "pergunta", "frente": "O que é isomeria?", "verso": "Compostos com a mesma fórmula molecular e estruturas diferentes.", "explicacao": "Ex.: etanol e éter dimetílico (C₂H₆O)."}, {"id": 2000001259, "trilha": "enem", "materia": "qui", "assunto": "Orgânica", "tipo": "pergunta", "frente": "O que são polímeros? Dê exemplos.", "verso": "Macromoléculas formadas pela repetição de unidades (monômeros): polietileno, PVC, PET, nylon, além de amido e proteínas.", "explicacao": "Plásticos são polímeros sintéticos."}, {"id": 2000001260, "trilha": "enem", "materia": "qui", "assunto": "Orgânica", "tipo": "pergunta", "frente": "Por que o plástico é um problema ambiental?", "verso": "Demora séculos para se degradar e forma microplásticos que contaminam a água e os seres vivos.", "explicacao": "Bioplásticos e reciclagem são alternativas."}, {"id": 2000001261, "trilha": "enem", "materia": "qui", "assunto": "Orgânica", "tipo": "pergunta", "frente": "O que é saponificação?", "verso": "Reação de um óleo ou gordura com base forte, produzindo sabão e glicerol.", "explicacao": "Óleo de cozinha usado pode virar sabão."}, {"id": 2000001262, "trilha": "enem", "materia": "qui", "assunto": "Química ambiental", "tipo": "pergunta", "frente": "O que é o efeito estufa?", "verso": "Retenção de parte do calor irradiado pela Terra por gases como CO₂, CH₄ e vapor d'água. É natural e necessário; o problema é sua intensificação.", "explicacao": "Intensificação pela queima de combustíveis fósseis e desmatamento."}, {"id": 2000001263, "trilha": "enem", "materia": "qui", "assunto": "Química ambiental", "tipo": "pergunta", "frente": "O que destrói a camada de ozônio?", "verso": "Principalmente os CFCs (clorofluorcarbonos), antes usados em geladeiras e aerossóis.", "explicacao": "Protocolo de Montreal (1987) os baniu."}, {"id": 2000001264, "trilha": "enem", "materia": "qui", "assunto": "Química ambiental", "tipo": "pergunta", "frente": "O que é eutrofização?", "verso": "Excesso de nutrientes (fosfatos e nitratos de esgoto e fertilizantes) na água causa proliferação de algas; sua decomposição consome o oxigênio e mata peixes.", "explicacao": "Aumenta a DBO (demanda bioquímica de oxigênio)."}, {"id": 2000001265, "trilha": "enem", "materia": "qui", "assunto": "Química ambiental", "tipo": "pergunta", "frente": "O que é biomagnificação?", "verso": "Acúmulo crescente de substâncias tóxicas (mercúrio, DDT) ao longo da cadeia alimentar.", "explicacao": "Predadores de topo têm as maiores concentrações."}, {"id": 2000001266, "trilha": "enem", "materia": "qui", "assunto": "Química ambiental", "tipo": "pergunta", "frente": "Por que o garimpo contamina rios com mercúrio?", "verso": "O mercúrio é usado para amalgamar o ouro e é lançado na água e no ar; vira metilmercúrio e se acumula nos peixes.", "explicacao": "Problema sério em terras indígenas da Amazônia."}, {"id": 2000001267, "trilha": "enem", "materia": "qui", "assunto": "Combustíveis", "tipo": "pergunta", "frente": "Por que o etanol é considerado renovável?", "verso": "Vem da cana-de-açúcar, e o CO₂ liberado na queima é reabsorvido no crescimento de novas plantas.", "explicacao": "Mesmo assim, há emissões na produção e no transporte."}, {"id": 2000001268, "trilha": "enem", "materia": "qui", "assunto": "Combustíveis", "tipo": "pergunta", "frente": "O que é biogás?", "verso": "Mistura rica em metano produzida pela decomposição anaeróbica de matéria orgânica (lixo, esterco).", "explicacao": "Biodigestores aproveitam esse gás."}, {"id": 2000001269, "trilha": "enem", "materia": "qui", "assunto": "Combustíveis", "tipo": "pares", "frente": "Combustão completa x incompleta.", "verso": "Completa: com oxigênio suficiente, gera CO₂ e água. Incompleta: pouco oxigênio, gera CO (tóxico) e fuligem.", "explicacao": "Por isso não se deve usar aquecedor a gás em local fechado."}, {"id": 2000001270, "trilha": "enem", "materia": "bio", "assunto": "Citologia", "tipo": "pares", "frente": "Célula procarionte x eucarionte.", "verso": "Procarionte: sem núcleo organizado nem organelas membranosas (bactérias). Eucarionte: com núcleo delimitado por membrana e organelas (animais, plantas, fungos, protozoários).", "explicacao": "Ambas têm ribossomos e membrana plasmática."}, {"id": 2000001271, "trilha": "enem", "materia": "bio", "assunto": "Citologia", "tipo": "pergunta", "frente": "Qual a função das mitocôndrias?", "verso": "Respiração celular: produzir energia (ATP) a partir da glicose e do oxigênio.", "explicacao": "Têm DNA próprio, herdado da mãe."}, {"id": 2000001272, "trilha": "enem", "materia": "bio", "assunto": "Citologia", "tipo": "pergunta", "frente": "Qual a função dos cloroplastos?", "verso": "Realizar a fotossíntese.", "explicacao": "Presentes em plantas e algas; contêm clorofila."}, {"id": 2000001273, "trilha": "enem", "materia": "bio", "assunto": "Citologia", "tipo": "pergunta", "frente": "Qual a função dos ribossomos?", "verso": "Síntese de proteínas.", "explicacao": "Podem estar livres ou no retículo endoplasmático rugoso."}, {"id": 2000001274, "trilha": "enem", "materia": "bio", "assunto": "Citologia", "tipo": "pergunta", "frente": "Qual a função do complexo golgiense?", "verso": "Modificar, empacotar e secretar substâncias, além de formar lisossomos.", "explicacao": "Também forma o acrossomo do espermatozoide."}, {"id": 2000001275, "trilha": "enem", "materia": "bio", "assunto": "Citologia", "tipo": "pares", "frente": "Célula animal x vegetal.", "verso": "Vegetal: parede celular de celulose, cloroplastos e grande vacúolo. Animal: sem parede celular, com centríolos.", "explicacao": "Ambas têm mitocôndrias."}, {"id": 2000001276, "trilha": "enem", "materia": "bio", "assunto": "Citologia", "tipo": "pares", "frente": "Transporte passivo x ativo.", "verso": "Passivo: a favor do gradiente, sem gasto de energia (difusão, osmose). Ativo: contra o gradiente, com gasto de ATP (bomba de sódio e potássio).", "explicacao": ""}, {"id": 2000001277, "trilha": "enem", "materia": "bio", "assunto": "Citologia", "tipo": "pares", "frente": "Mitose x meiose.", "verso": "Mitose: 1 célula forma 2 idênticas, mesmo número de cromossomos (crescimento, regeneração). Meiose: 1 célula forma 4 com metade dos cromossomos (gametas), com variabilidade.", "explicacao": "Meiose tem crossing-over."}, {"id": 2000001278, "trilha": "enem", "materia": "bio", "assunto": "Metabolismo", "tipo": "lacuna", "frente": "Equação da fotossíntese: 6 CO₂ + 6 H₂O + luz → C₆H₁₂O₆ + 6 ___.", "verso": "O₂ (oxigênio).", "explicacao": "O oxigênio liberado vem da água."}, {"id": 2000001279, "trilha": "enem", "materia": "bio", "assunto": "Metabolismo", "tipo": "pares", "frente": "Respiração aeróbica x fermentação.", "verso": "Aeróbica: usa oxigênio e gera muito ATP (cerca de 30 a 38). Fermentação: sem oxigênio, gera só 2 ATP, com produtos como álcool ou ácido lático.", "explicacao": "Fermentação alcoólica: pão e bebidas; lática: iogurte e músculo cansado."}, {"id": 2000001280, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "O que diz a 1ª lei de Mendel?", "verso": "Cada característica é determinada por um par de fatores (genes) que se separam na formação dos gametas.", "explicacao": "Lei da segregação."}, {"id": 2000001281, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "Cruzamento Aa × Aa: qual a proporção fenotípica com dominância completa?", "verso": "3 dominantes : 1 recessivo.", "explicacao": "Genotípica: 1 AA : 2 Aa : 1 aa."}, {"id": 2000001282, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pares", "frente": "Genótipo x fenótipo.", "verso": "Genótipo: os genes do indivíduo. Fenótipo: as características observáveis (genótipo + ambiente).", "explicacao": ""}, {"id": 2000001283, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "Como se herda o daltonismo e a hemofilia?", "verso": "Ligados ao cromossomo X, recessivos; por isso são mais comuns em homens.", "explicacao": "A mulher portadora (XᴬXᵃ) não manifesta, mas transmite."}, {"id": 2000001284, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "Quais os genótipos do sistema ABO?", "verso": "A: IᴬIᴬ ou Iᴬi; B: IᴮIᴮ ou Iᴮi; AB: IᴬIᴮ; O: ii.", "explicacao": "Iᴬ e Iᴮ são codominantes."}, {"id": 2000001285, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "Quem é doador e receptor universal no sistema ABO?", "verso": "Doador universal: tipo O. Receptor universal: tipo AB.", "explicacao": "Também é preciso considerar o fator Rh."}, {"id": 2000001286, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "O que é a eritroblastose fetal?", "verso": "Destruição das hemácias do feto Rh+ por anticorpos da mãe Rh− sensibilizada numa gestação anterior.", "explicacao": "Prevenida com soro anti-Rh após o parto."}, {"id": 2000001287, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pares", "frente": "DNA x RNA.", "verso": "DNA: dupla-hélice, desoxirribose, bases A, T, C, G; guarda a informação. RNA: fita simples, ribose, uracila no lugar da timina; atua na síntese de proteínas.", "explicacao": "Replicação, transcrição e tradução."}, {"id": 2000001288, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "O que é um transgênico?", "verso": "Organismo que recebeu gene de outra espécie por engenharia genética.", "explicacao": "Ex.: milho Bt, resistente a insetos."}, {"id": 2000001289, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "O que é clonagem?", "verso": "Produção de indivíduos geneticamente idênticos a outro.", "explicacao": "Ovelha Dolly (1996), por transferência de núcleo."}, {"id": 2000001290, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "O que são células-tronco?", "verso": "Células não especializadas capazes de se dividir e originar diferentes tipos de células.", "explicacao": "Embrionárias são as mais versáteis."}, {"id": 2000001291, "trilha": "enem", "materia": "bio", "assunto": "Genética", "tipo": "pergunta", "frente": "O que é a técnica CRISPR?", "verso": "Ferramenta de edição genética que corta e altera trechos específicos do DNA.", "explicacao": "Rendeu o Nobel de Química de 2020."}, {"id": 2000001292, "trilha": "enem", "materia": "bio", "assunto": "Evolução", "tipo": "pares", "frente": "Lamarckismo x darwinismo.", "verso": "Lamarck: uso e desuso e herança dos caracteres adquiridos (ideia rejeitada). Darwin: seleção natural, os mais adaptados sobrevivem e se reproduzem mais.", "explicacao": "Girafa: pescoço longo selecionado (Darwin), não esticado (Lamarck)."}, {"id": 2000001293, "trilha": "enem", "materia": "bio", "assunto": "Evolução", "tipo": "pergunta", "frente": "O que é a teoria sintética da evolução?", "verso": "Darwinismo somado à genética: mutação e recombinação geram variabilidade, e a seleção natural atua sobre ela.", "explicacao": "Neodarwinismo."}, {"id": 2000001294, "trilha": "enem", "materia": "bio", "assunto": "Evolução", "tipo": "pergunta", "frente": "Por que bactérias resistentes a antibióticos se espalham?", "verso": "O uso do antibiótico mata as sensíveis e seleciona as resistentes, que se multiplicam.", "explicacao": "Uso incorreto de antibióticos acelera o processo."}, {"id": 2000001295, "trilha": "enem", "materia": "bio", "assunto": "Evolução", "tipo": "pares", "frente": "Órgãos homólogos x análogos.", "verso": "Homólogos: mesma origem embrionária, funções podem diferir (braço humano e asa do morcego) — evolução divergente. Análogos: mesma função, origens diferentes (asa de inseto e de ave) — evolução convergente.", "explicacao": ""}, {"id": 2000001296, "trilha": "enem", "materia": "bio", "assunto": "Ecologia", "tipo": "pares", "frente": "Cadeia alimentar x teia alimentar.", "verso": "Cadeia: sequência linear de quem come quem. Teia: conjunto de cadeias interligadas de um ecossistema.", "explicacao": "Produtores → consumidores → decompositores."}, {"id": 2000001297, "trilha": "enem", "materia": "bio", "assunto": "Ecologia", "tipo": "pergunta", "frente": "Por que a energia diminui ao longo da cadeia alimentar?", "verso": "Parte se perde como calor e em atividades de cada nível; cerca de 10% passa ao nível seguinte.", "explicacao": "Por isso cadeias raramente passam de 4 ou 5 níveis."}, {"id": 2000001298, "trilha": "enem", "materia": "bio", "assunto": "Ecologia", "tipo": "pares", "frente": "Habitat x nicho ecológico.", "verso": "Habitat: o “endereço”, onde a espécie vive. Nicho: a “profissão”, o papel que desempenha (o que come, quando age, como se reproduz).", "explicacao": ""}, {"id": 2000001299, "trilha": "enem", "materia": "bio", "assunto": "Ecologia", "tipo": "pares", "frente": "Mutualismo x comensalismo x parasitismo.", "verso": "Mutualismo: ambos ganham, com dependência (líquen). Comensalismo: um ganha e o outro não perde (rêmora e tubarão). Parasitismo: um ganha e o outro é prejudicado.", "explicacao": "Protocooperação: ambos ganham, sem dependência."}, {"id": 2000001300, "trilha": "enem", "materia": "bio", "assunto": "Ecologia", "tipo": "pergunta", "frente": "O que é sucessão ecológica?", "verso": "Mudança gradual de uma comunidade ao longo do tempo, das espécies pioneiras até a comunidade clímax.", "explicacao": "Primária: em área nunca ocupada; secundária: em área já ocupada e perturbada."}, {"id": 2000001301, "trilha": "enem", "materia": "bio", "assunto": "Ecologia", "tipo": "pergunta", "frente": "Qual o papel dos decompositores?", "verso": "Decompõem a matéria orgânica morta e devolvem nutrientes ao ambiente.", "explicacao": "Bactérias e fungos."}, {"id": 2000001302, "trilha": "enem", "materia": "bio", "assunto": "Ciclos", "tipo": "pergunta", "frente": "Qual o papel das bactérias no ciclo do nitrogênio?", "verso": "Fixam o N₂ do ar (como as do gênero Rhizobium nas raízes de leguminosas), fazem nitrificação e desnitrificação.", "explicacao": "Rotação de culturas com leguminosas fertiliza o solo."}, {"id": 2000001303, "trilha": "enem", "materia": "bio", "assunto": "Ciclos", "tipo": "pergunta", "frente": "Quais processos retiram e devolvem carbono à atmosfera?", "verso": "Retira: fotossíntese. Devolve: respiração, decomposição e queima de combustíveis e florestas.", "explicacao": "O excesso de CO₂ intensifica o efeito estufa."}, {"id": 2000001304, "trilha": "enem", "materia": "bio", "assunto": "Biomas", "tipo": "pergunta", "frente": "Quais as características da Caatinga?", "verso": "Clima semiárido, chuvas irregulares, plantas xerófitas (cactos, folhas pequenas ou caducas).", "explicacao": "Bioma exclusivamente brasileiro."}, {"id": 2000001305, "trilha": "enem", "materia": "bio", "assunto": "Biomas", "tipo": "pergunta", "frente": "Quais as características do Cerrado?", "verso": "Árvores de troncos tortuosos e casca grossa, raízes profundas, solo ácido e estações chuvosa e seca bem definidas.", "explicacao": "Berço de grandes bacias hidrográficas; muito ameaçado pela agropecuária."}, {"id": 2000001306, "trilha": "enem", "materia": "bio", "assunto": "Biomas", "tipo": "pergunta", "frente": "Quais as características da Mata Atlântica?", "verso": "Floresta úmida da costa brasileira, com enorme biodiversidade; restam cerca de 12% de sua cobertura original.", "explicacao": "Bioma mais devastado do país."}, {"id": 2000001307, "trilha": "enem", "materia": "bio", "assunto": "Biomas", "tipo": "pergunta", "frente": "O que é o Pantanal?", "verso": "Maior planície alagável do mundo, com cheias e secas sazonais e grande biodiversidade.", "explicacao": "Fica em MT e MS, chegando à Bolívia e ao Paraguai."}, {"id": 2000001308, "trilha": "enem", "materia": "bio", "assunto": "Biomas", "tipo": "pergunta", "frente": "Por que o solo da Amazônia é pobre apesar da floresta exuberante?", "verso": "Os nutrientes estão na própria biomassa e são reciclados rapidamente; sem a floresta, a chuva lava o solo.", "explicacao": "Desmatamento leva ao empobrecimento rápido."}, {"id": 2000001309, "trilha": "enem", "materia": "bio", "assunto": "Fisiologia", "tipo": "pergunta", "frente": "Qual a função das hemácias?", "verso": "Transportar oxigênio, ligado à hemoglobina.", "explicacao": "Leucócitos: defesa. Plaquetas: coagulação."}, {"id": 2000001310, "trilha": "enem", "materia": "bio", "assunto": "Fisiologia", "tipo": "pergunta", "frente": "Qual a função da insulina?", "verso": "Reduz a glicose no sangue, facilitando sua entrada nas células.", "explicacao": "Produzida pelo pâncreas. O glucagon tem efeito oposto."}, {"id": 2000001311, "trilha": "enem", "materia": "bio", "assunto": "Fisiologia", "tipo": "pergunta", "frente": "Onde ocorre a maior parte da absorção de nutrientes?", "verso": "No intestino delgado, graças às vilosidades.", "explicacao": "O intestino grosso absorve principalmente água."}, {"id": 2000001312, "trilha": "enem", "materia": "bio", "assunto": "Fisiologia", "tipo": "pergunta", "frente": "Qual a função dos rins?", "verso": "Filtrar o sangue, eliminar resíduos (como a ureia) e regular a água e os sais do corpo.", "explicacao": "Unidade funcional: néfron."}, {"id": 2000001313, "trilha": "enem", "materia": "bio", "assunto": "Fisiologia", "tipo": "pergunta", "frente": "Onde ocorrem as trocas gasosas na respiração?", "verso": "Nos alvéolos pulmonares, por difusão.", "explicacao": "O oxigênio vai para o sangue e o CO₂ sai."}, {"id": 2000001314, "trilha": "enem", "materia": "bio", "assunto": "Fisiologia", "tipo": "pares", "frente": "Circulação pulmonar x sistêmica.", "verso": "Pulmonar (pequena): coração → pulmões → coração, para oxigenar o sangue. Sistêmica (grande): coração → corpo → coração, para distribuir oxigênio.", "explicacao": "O ventrículo esquerdo bombeia para o corpo."}, {"id": 2000001315, "trilha": "enem", "materia": "bio", "assunto": "Fisiologia", "tipo": "pergunta", "frente": "Qual a função do hormônio tireoidiano e o que a falta de iodo causa?", "verso": "Regula o metabolismo. A falta de iodo causa bócio.", "explicacao": "Por isso o sal de cozinha é iodado."}, {"id": 2000001316, "trilha": "enem", "materia": "bio", "assunto": "Imunologia", "tipo": "pares", "frente": "Vacina x soro.", "verso": "Vacina: antígeno que induz o corpo a produzir anticorpos e memória (imunização ativa, preventiva). Soro: anticorpos prontos (imunização passiva, de efeito imediato e curto).", "explicacao": "Soro antiofídico em picada de cobra."}, {"id": 2000001317, "trilha": "enem", "materia": "bio", "assunto": "Imunologia", "tipo": "pergunta", "frente": "O que é imunidade de rebanho?", "verso": "Quando uma parcela grande da população está imune, o agente circula pouco e protege também quem não pode se vacinar.", "explicacao": "Por isso a cobertura vacinal coletiva é importante."}, {"id": 2000001318, "trilha": "enem", "materia": "bio", "assunto": "Imunologia", "tipo": "pergunta", "frente": "Por que os antibióticos não funcionam contra vírus?", "verso": "Atuam em estruturas de bactérias (parede celular, ribossomos bacterianos); vírus não têm essas estruturas.", "explicacao": "Antivirais são outra classe de medicamentos."}, {"id": 2000001319, "trilha": "enem", "materia": "bio", "assunto": "Saúde", "tipo": "pergunta", "frente": "Como se transmite a dengue e como prevenir?", "verso": "Pela picada da fêmea do mosquito Aedes aegypti. Prevenção: eliminar água parada.", "explicacao": "O mesmo mosquito transmite zika, chikungunya e febre amarela urbana."}, {"id": 2000001320, "trilha": "enem", "materia": "bio", "assunto": "Saúde", "tipo": "pergunta", "frente": "Como se transmite a doença de Chagas?", "verso": "Pelas fezes do inseto barbeiro contaminadas com o protozoário Trypanosoma cruzi, que entram pela picada ou mucosas; também por alimentos contaminados (açaí, caldo de cana).", "explicacao": "Atinge principalmente o coração."}, {"id": 2000001321, "trilha": "enem", "materia": "bio", "assunto": "Saúde", "tipo": "pergunta", "frente": "Como se transmite a esquistossomose?", "verso": "Pelas larvas (cercárias) que penetram a pele em água doce contaminada; o caramujo é hospedeiro intermediário.", "explicacao": "Prevenção: saneamento básico."}, {"id": 2000001322, "trilha": "enem", "materia": "bio", "assunto": "Saúde", "tipo": "pergunta", "frente": "Como se transmite a malária?", "verso": "Pela picada da fêmea do mosquito Anopheles infectada pelo protozoário Plasmodium.", "explicacao": "Mais comum na Região Norte."}, {"id": 2000001323, "trilha": "enem", "materia": "bio", "assunto": "Saúde", "tipo": "pergunta", "frente": "Qual o agente e como se transmite a tuberculose?", "verso": "A bactéria Mycobacterium tuberculosis, pelo ar (tosse, espirro).", "explicacao": "A vacina BCG protege contra as formas graves."}, {"id": 2000001324, "trilha": "enem", "materia": "bio", "assunto": "Saúde", "tipo": "pergunta", "frente": "Como se previne a leptospirose?", "verso": "Evitando contato com água de enchentes e controlando ratos, cuja urina transmite a bactéria.", "explicacao": ""}, {"id": 2000001325, "trilha": "enem", "materia": "bio", "assunto": "Saúde", "tipo": "pergunta", "frente": "Qual a importância do saneamento básico para a saúde?", "verso": "Evita doenças de veiculação hídrica e fecal-oral, como diarreias, hepatite A, cólera e verminoses.", "explicacao": "Água tratada e esgoto coletado e tratado."}, {"id": 2000001326, "trilha": "enem", "materia": "bio", "assunto": "Saúde", "tipo": "pergunta", "frente": "Como se transmite o HIV?", "verso": "Por relação sexual sem preservativo, sangue contaminado, compartilhamento de seringas e da mãe para o filho (gestação, parto, amamentação).", "explicacao": "Não se transmite por abraço, beijo social ou talheres."}, {"id": 2000001327, "trilha": "enem", "materia": "bio", "assunto": "Botânica", "tipo": "pares", "frente": "Briófitas x pteridófitas x gimnospermas x angiospermas.", "verso": "Briófitas: sem vasos (musgos). Pteridófitas: com vasos, sem sementes (samambaias). Gimnospermas: sementes nuas, sem fruto (pinheiros). Angiospermas: flores e frutos.", "explicacao": "Angiospermas são a maioria das plantas atuais."}, {"id": 2000001328, "trilha": "enem", "materia": "bio", "assunto": "Botânica", "tipo": "pares", "frente": "Xilema x floema.", "verso": "Xilema: leva água e sais minerais da raiz às folhas (seiva bruta). Floema: leva os açúcares produzidos nas folhas para o resto da planta (seiva elaborada).", "explicacao": "Anel de Malpighi corta o floema."}, {"id": 2000001329, "trilha": "enem", "materia": "bio", "assunto": "Botânica", "tipo": "pergunta", "frente": "Para que servem os estômatos?", "verso": "Trocas gasosas e controle da transpiração da planta.", "explicacao": "Ficam principalmente nas folhas."}, {"id": 2000001330, "trilha": "enem", "materia": "bio", "assunto": "Botânica", "tipo": "pergunta", "frente": "Qual a função do fruto nas angiospermas?", "verso": "Proteger a semente e ajudar na dispersão.", "explicacao": "Dispersão por animais, vento ou água."}, {"id": 2000001331, "trilha": "enem", "materia": "bio", "assunto": "Zoologia", "tipo": "pergunta", "frente": "Quais as características dos mamíferos?", "verso": "Pelos, glândulas mamárias, endotermia (temperatura constante) e, na maioria, desenvolvimento do embrião no útero.", "explicacao": "Ornitorrinco e equidna botam ovos."}, {"id": 2000001332, "trilha": "enem", "materia": "bio", "assunto": "Zoologia", "tipo": "pergunta", "frente": "Que adaptações permitiram aos répteis conquistar o ambiente terrestre?", "verso": "Ovo com casca e anexos embrionários (âmnio), pele seca com escamas e fecundação interna.", "explicacao": "Não dependem da água para reprodução."}, {"id": 2000001333, "trilha": "enem", "materia": "bio", "assunto": "Zoologia", "tipo": "pergunta", "frente": "Por que os anfíbios dependem da água?", "verso": "A fecundação geralmente é externa, os ovos não têm casca e as larvas (girinos) são aquáticas; a pele precisa estar úmida para respirar.", "explicacao": "São bioindicadores de qualidade ambiental."}, {"id": 2000001334, "trilha": "enem", "materia": "bio", "assunto": "Zoologia", "tipo": "pergunta", "frente": "O que é metamorfose completa?", "verso": "Desenvolvimento em quatro fases: ovo, larva, pupa e adulto.", "explicacao": "Borboletas e moscas. Gafanhotos têm metamorfose incompleta."}, {"id": 2000001335, "trilha": "enem", "materia": "bio", "assunto": "Microbiologia", "tipo": "pergunta", "frente": "Por que os vírus são considerados parasitas intracelulares obrigatórios?", "verso": "Não têm metabolismo próprio e só se reproduzem dentro de células vivas.", "explicacao": "Não são formados por células."}, {"id": 2000001336, "trilha": "enem", "materia": "bio", "assunto": "Microbiologia", "tipo": "pergunta", "frente": "Cite usos benéficos de fungos e bactérias.", "verso": "Produção de pão, queijo, iogurte, vinho, antibióticos (penicilina), decomposição e fixação de nitrogênio.", "explicacao": "A penicilina vem do fungo Penicillium."}, {"id": 2000001337, "trilha": "enem", "materia": "bio", "assunto": "Reprodução", "tipo": "pergunta", "frente": "Quais métodos contraceptivos também previnem ISTs?", "verso": "Somente os preservativos (camisinha masculina e feminina).", "explicacao": "Pílula e DIU não protegem contra ISTs."}, {"id": 2000001338, "trilha": "enem", "materia": "bio", "assunto": "Reprodução", "tipo": "pergunta", "frente": "Onde normalmente ocorre a fecundação humana?", "verso": "Na tuba uterina.", "explicacao": "O embrião se implanta no útero (nidação)."}, {"id": 2000001339, "trilha": "enem", "materia": "bio", "assunto": "Conservação", "tipo": "pergunta", "frente": "Por que a fragmentação de habitats ameaça espécies?", "verso": "Isola populações, reduz a variabilidade genética e aumenta o efeito de borda.", "explicacao": "Corredores ecológicos conectam fragmentos."}, {"id": 2000001340, "trilha": "enem", "materia": "bio", "assunto": "Conservação", "tipo": "pergunta", "frente": "O que são espécies exóticas invasoras e por que preocupam?", "verso": "Espécies introduzidas fora de sua área natural que se espalham sem predadores, competindo com as nativas.", "explicacao": "Ex.: javali, coral-sol, caramujo-africano."}, {"id": 2000001341, "trilha": "enem", "materia": "his", "assunto": "Antiguidade", "tipo": "pergunta", "frente": "O que foi a democracia ateniense e quem participava dela?", "verso": "Governo em que os cidadãos votavam diretamente nas assembleias; só eram cidadãos homens livres, adultos, filhos de atenienses.", "explicacao": "Mulheres, estrangeiros (metecos) e escravizados ficavam de fora."}, {"id": 2000001342, "trilha": "enem", "materia": "his", "assunto": "Antiguidade", "tipo": "pares", "frente": "República romana x Império romano.", "verso": "República: poder do Senado e de magistrados eleitos (cônsules), com conflitos entre patrícios e plebeus. Império: poder centralizado no imperador, a partir de Augusto (27 a.C.).", "explicacao": "“Pão e circo” era política do Império."}, {"id": 2000001343, "trilha": "enem", "materia": "his", "assunto": "Idade Média", "tipo": "pergunta", "frente": "O que foi o feudalismo?", "verso": "Sistema da Europa medieval baseado na terra (feudo), em relações de suserania e vassalagem e na servidão dos camponeses.", "explicacao": "Economia agrária e pouco monetarizada."}, {"id": 2000001344, "trilha": "enem", "materia": "his", "assunto": "Idade Média", "tipo": "pergunta", "frente": "Qual era o papel da Igreja Católica na Idade Média?", "verso": "Era a principal instituição: concentrava terras, conhecimento, poder político e ditava valores (teocentrismo).", "explicacao": ""}, {"id": 2000001345, "trilha": "enem", "materia": "his", "assunto": "Idade Moderna", "tipo": "pergunta", "frente": "O que foi o Renascimento?", "verso": "Movimento cultural (séc. XIV–XVI) que valorizou o ser humano (antropocentrismo), a razão e a cultura greco-romana.", "explicacao": "Leonardo da Vinci, Michelangelo."}, {"id": 2000001346, "trilha": "enem", "materia": "his", "assunto": "Idade Moderna", "tipo": "pergunta", "frente": "O que foi a Reforma Protestante?", "verso": "Ruptura com a Igreja Católica iniciada por Martinho Lutero em 1517, criticando a venda de indulgências.", "explicacao": "A Igreja respondeu com a Contrarreforma (Concílio de Trento)."}, {"id": 2000001347, "trilha": "enem", "materia": "his", "assunto": "Idade Moderna", "tipo": "pergunta", "frente": "O que foi o mercantilismo?", "verso": "Conjunto de práticas econômicas dos Estados absolutistas: metalismo, balança comercial favorável, protecionismo e exploração colonial.", "explicacao": ""}, {"id": 2000001348, "trilha": "enem", "materia": "his", "assunto": "Idade Moderna", "tipo": "pergunta", "frente": "O que foi o Iluminismo?", "verso": "Movimento do séc. XVIII que defendia a razão, a liberdade, a igualdade perante a lei e criticava o absolutismo e a intolerância religiosa.", "explicacao": "Montesquieu (separação dos poderes), Rousseau, Voltaire."}, {"id": 2000001349, "trilha": "enem", "materia": "his", "assunto": "Idade Contemporânea", "tipo": "pergunta", "frente": "Qual o lema e a importância da Revolução Francesa (1789)?", "verso": "“Liberdade, igualdade, fraternidade”. Derrubou o Antigo Regime e difundiu os direitos do homem e do cidadão.", "explicacao": "Marco do início da Idade Contemporânea."}, {"id": 2000001350, "trilha": "enem", "materia": "his", "assunto": "Idade Contemporânea", "tipo": "pergunta", "frente": "Quais as consequências da Revolução Industrial?", "verso": "Produção em fábricas com máquinas, urbanização, formação do proletariado, longas jornadas e exploração do trabalho infantil.", "explicacao": "Começou na Inglaterra no séc. XVIII."}, {"id": 2000001351, "trilha": "enem", "materia": "his", "assunto": "Idade Contemporânea", "tipo": "pares", "frente": "Liberalismo x socialismo.", "verso": "Liberalismo: livre mercado, propriedade privada e Estado mínimo. Socialismo: crítica à exploração capitalista, propriedade coletiva dos meios de produção.", "explicacao": "Marx e Engels: “Manifesto comunista” (1848)."}, {"id": 2000001352, "trilha": "enem", "materia": "his", "assunto": "Idade Contemporânea", "tipo": "pergunta", "frente": "O que foi o imperialismo (neocolonialismo) do séc. XIX?", "verso": "Dominação da África e da Ásia pelas potências industriais em busca de matérias-primas e mercados.", "explicacao": "Conferência de Berlim (1884–1885) partilhou a África."}, {"id": 2000001353, "trilha": "enem", "materia": "his", "assunto": "Século XX", "tipo": "pergunta", "frente": "Quais as causas da Primeira Guerra Mundial (1914–1918)?", "verso": "Disputas imperialistas, nacionalismos, corrida armamentista e sistema de alianças; o estopim foi o assassinato do arquiduque Francisco Ferdinando.", "explicacao": "Terminou com o Tratado de Versalhes."}, {"id": 2000001354, "trilha": "enem", "materia": "his", "assunto": "Século XX", "tipo": "pergunta", "frente": "O que foi a Crise de 1929?", "verso": "Quebra da Bolsa de Nova York que gerou recessão mundial, desemprego em massa e queda do comércio.", "explicacao": "No Brasil, derrubou o preço do café."}, {"id": 2000001355, "trilha": "enem", "materia": "his", "assunto": "Século XX", "tipo": "pergunta", "frente": "Quais as características do nazifascismo?", "verso": "Totalitarismo, nacionalismo extremo, culto ao líder, anticomunismo, militarismo, propaganda e perseguição a minorias.", "explicacao": "O Holocausto matou cerca de 6 milhões de judeus."}, {"id": 2000001356, "trilha": "enem", "materia": "his", "assunto": "Século XX", "tipo": "pergunta", "frente": "O que foi a Guerra Fria?", "verso": "Disputa entre EUA (capitalismo) e URSS (socialismo) de 1947 a 1991, sem confronto direto entre eles, com corrida armamentista e espacial e guerras em outros países.", "explicacao": "Muro de Berlim caiu em 1989."}, {"id": 2000001357, "trilha": "enem", "materia": "his", "assunto": "Século XX", "tipo": "pergunta", "frente": "O que foi a descolonização da África e da Ásia?", "verso": "Processo de independência das colônias após a Segunda Guerra, por vias pacíficas ou guerras.", "explicacao": "Índia (1947), com Gandhi; Argélia, Angola e Moçambique, com guerras."}, {"id": 2000001358, "trilha": "enem", "materia": "his", "assunto": "Século XX", "tipo": "pergunta", "frente": "O que foi o apartheid?", "verso": "Regime de segregação racial na África do Sul (1948–1994).", "explicacao": "Nelson Mandela tornou-se o primeiro presidente negro do país."}, {"id": 2000001359, "trilha": "enem", "materia": "his", "assunto": "Brasil Colônia", "tipo": "pergunta", "frente": "O que foram as capitanias hereditárias?", "verso": "Divisão do território em faixas entregues a donatários, que deviam povoar e explorar a terra (1534).", "explicacao": "A maioria fracassou; vieram depois os governos-gerais."}, {"id": 2000001360, "trilha": "enem", "materia": "his", "assunto": "Brasil Colônia", "tipo": "pergunta", "frente": "Como funcionava o engenho de açúcar colonial?", "verso": "Grande propriedade monocultora (plantation), com mão de obra escravizada e produção voltada à exportação.", "explicacao": "Casa-grande e senzala."}, {"id": 2000001361, "trilha": "enem", "materia": "his", "assunto": "Brasil Colônia", "tipo": "pergunta", "frente": "O que foi o Quilombo dos Palmares?", "verso": "O maior quilombo do Brasil colonial, na serra da Barriga (AL), que resistiu por quase um século; Zumbi foi seu líder mais conhecido.", "explicacao": "20 de novembro, Dia da Consciência Negra, lembra a morte de Zumbi."}, {"id": 2000001362, "trilha": "enem", "materia": "his", "assunto": "Brasil Colônia", "tipo": "pergunta", "frente": "O que foi o ciclo do ouro no séc. XVIII?", "verso": "Mineração em Minas Gerais, Goiás e Mato Grosso, que deslocou o eixo econômico para o Sudeste e levou a capital para o Rio de Janeiro (1763).", "explicacao": "Cobrança do quinto e da derrama."}, {"id": 2000001363, "trilha": "enem", "materia": "his", "assunto": "Brasil Colônia", "tipo": "pares", "frente": "Inconfidência Mineira x Conjuração Baiana.", "verso": "Mineira (1789): elite de Minas, contra a derrama, sem propor fim da escravidão; Tiradentes foi executado. Baiana (1798): popular, com negros e mulatos, defendia a abolição e a igualdade.", "explicacao": "Ambas inspiradas no Iluminismo."}, {"id": 2000001364, "trilha": "enem", "materia": "his", "assunto": "Brasil Colônia", "tipo": "pergunta", "frente": "Por que a família real portuguesa veio ao Brasil em 1808?", "verso": "Fugindo da invasão de Napoleão a Portugal, com apoio inglês.", "explicacao": "Abertura dos portos às nações amigas."}, {"id": 2000001365, "trilha": "enem", "materia": "his", "assunto": "Brasil Império", "tipo": "pergunta", "frente": "Como foi a independência do Brasil?", "verso": "Proclamada por D. Pedro em 1822, mantendo a monarquia, a escravidão e a estrutura agrária.", "explicacao": "Independência negociada, sem grandes rupturas sociais."}, {"id": 2000001366, "trilha": "enem", "materia": "his", "assunto": "Brasil Império", "tipo": "pergunta", "frente": "O que foi o Poder Moderador na Constituição de 1824?", "verso": "Um quarto poder exclusivo do imperador, acima dos demais.", "explicacao": "Voto censitário (por renda)."}, {"id": 2000001367, "trilha": "enem", "materia": "his", "assunto": "Brasil Império", "tipo": "pergunta", "frente": "O que foi o Período Regencial (1831–1840)?", "verso": "Período entre a abdicação de D. Pedro I e o Golpe da Maioridade, marcado por revoltas provinciais.", "explicacao": "Cabanagem, Sabinada, Balaiada e Farroupilha."}, {"id": 2000001368, "trilha": "enem", "materia": "his", "assunto": "Brasil Império", "tipo": "pergunta", "frente": "Quais foram as leis abolicionistas antes da Lei Áurea?", "verso": "Eusébio de Queirós (1850, fim do tráfico), Lei do Ventre Livre (1871) e Lei dos Sexagenários (1885).", "explicacao": "Lei Áurea: 13 de maio de 1888."}, {"id": 2000001369, "trilha": "enem", "materia": "his", "assunto": "Brasil Império", "tipo": "pergunta", "frente": "O que aconteceu com os libertos após a abolição?", "verso": "Ficaram sem terra, indenização ou políticas de inclusão, sendo marginalizados.", "explicacao": "Raiz da desigualdade racial no Brasil."}, {"id": 2000001370, "trilha": "enem", "materia": "his", "assunto": "Brasil Império", "tipo": "pergunta", "frente": "O que foi a Lei de Terras de 1850?", "verso": "Lei que permitiu o acesso à terra apenas por compra, dificultando que pobres, imigrantes e libertos se tornassem proprietários.", "explicacao": "Mesmo ano do fim do tráfico negreiro."}, {"id": 2000001371, "trilha": "enem", "materia": "his", "assunto": "República Velha", "tipo": "pergunta", "frente": "O que foi a política do café com leite?", "verso": "Alternância de presidentes de São Paulo (café) e Minas Gerais (leite) na República Velha.", "explicacao": "Rompida em 1930."}, {"id": 2000001372, "trilha": "enem", "materia": "his", "assunto": "República Velha", "tipo": "pergunta", "frente": "O que foi o coronelismo?", "verso": "Poder local dos grandes fazendeiros que controlavam o voto da população (voto de cabresto).", "explicacao": "Voto aberto facilitava o controle."}, {"id": 2000001373, "trilha": "enem", "materia": "his", "assunto": "República Velha", "tipo": "pergunta", "frente": "O que foi a Guerra de Canudos?", "verso": "Conflito no sertão da Bahia (1896–1897) entre o Exército e a comunidade liderada por Antônio Conselheiro, destruída.", "explicacao": "Narrado em “Os sertões”, de Euclides da Cunha."}, {"id": 2000001374, "trilha": "enem", "materia": "his", "assunto": "República Velha", "tipo": "pergunta", "frente": "O que foi a Revolta da Vacina (1904)?", "verso": "Revolta popular no Rio de Janeiro contra a vacinação obrigatória contra a varíola, somada à insatisfação com reformas urbanas que expulsaram pobres do centro.", "explicacao": "Oswaldo Cruz era o responsável pela saúde pública."}, {"id": 2000001375, "trilha": "enem", "materia": "his", "assunto": "República Velha", "tipo": "pergunta", "frente": "O que foi a Revolta da Chibata (1910)?", "verso": "Rebelião de marinheiros, liderados por João Cândido, contra os castigos físicos na Marinha.", "explicacao": ""}, {"id": 2000001376, "trilha": "enem", "materia": "his", "assunto": "Era Vargas", "tipo": "pergunta", "frente": "Quais as marcas da Era Vargas (1930–1945)?", "verso": "Centralização do poder, industrialização, criação da CLT (1943), trabalhismo, populismo e o Estado Novo (1937–1945), ditadura com censura.", "explicacao": "Criou a Petrobras em 1953, em seu segundo governo."}, {"id": 2000001377, "trilha": "enem", "materia": "his", "assunto": "Era Vargas", "tipo": "pergunta", "frente": "Quando as mulheres conquistaram o direito ao voto no Brasil?", "verso": "Em 1932, pelo Código Eleitoral.", "explicacao": "Confirmado na Constituição de 1934."}, {"id": 2000001378, "trilha": "enem", "materia": "his", "assunto": "República Democrática", "tipo": "pergunta", "frente": "Qual a marca do governo Juscelino Kubitschek?", "verso": "O Plano de Metas (“50 anos em 5”), a construção de Brasília e a entrada de indústrias estrangeiras, como as automobilísticas.", "explicacao": "Aumento da dívida externa e da inflação."}, {"id": 2000001379, "trilha": "enem", "materia": "his", "assunto": "Ditadura militar", "tipo": "pergunta", "frente": "O que foi o AI-5 (1968)?", "verso": "O mais duro ato institucional da ditadura: fechou o Congresso, suspendeu o habeas corpus para crimes políticos e ampliou a censura.", "explicacao": "Início dos “anos de chumbo”."}, {"id": 2000001380, "trilha": "enem", "materia": "his", "assunto": "Ditadura militar", "tipo": "pergunta", "frente": "O que foi o “milagre econômico”?", "verso": "Período de alto crescimento econômico (1968–1973), com aumento da dívida externa e da concentração de renda.", "explicacao": "“Fazer o bolo crescer para depois dividir”."}, {"id": 2000001381, "trilha": "enem", "materia": "his", "assunto": "Ditadura militar", "tipo": "pergunta", "frente": "O que foi a Lei da Anistia de 1979?", "verso": "Perdoou crimes políticos de opositores e também de agentes do Estado, permitindo a volta dos exilados.", "explicacao": "A anistia a torturadores é muito criticada."}, {"id": 2000001382, "trilha": "enem", "materia": "his", "assunto": "Redemocratização", "tipo": "pergunta", "frente": "O que foi o movimento Diretas Já?", "verso": "Campanha de 1983–1984 por eleições diretas para presidente; a emenda foi rejeitada.", "explicacao": "Tancredo Neves foi eleito indiretamente em 1985."}, {"id": 2000001383, "trilha": "enem", "materia": "his", "assunto": "Redemocratização", "tipo": "pergunta", "frente": "Por que a Constituição de 1988 é chamada de “Constituição Cidadã”?", "verso": "Pela ampliação de direitos sociais e individuais, criação do SUS, voto facultativo para analfabetos e jovens de 16 e 17 anos.", "explicacao": "Marco da redemocratização."}, {"id": 2000001384, "trilha": "enem", "materia": "his", "assunto": "Brasil contemporâneo", "tipo": "pergunta", "frente": "O que foi o Plano Real (1994)?", "verso": "Plano econômico que controlou a hiperinflação com a criação do real.", "explicacao": ""}, {"id": 2000001385, "trilha": "enem", "materia": "his", "assunto": "História indígena", "tipo": "pergunta", "frente": "Por que o termo “descobrimento” é criticado?", "verso": "Porque o território já era habitado por milhões de indígenas; fala-se em chegada dos portugueses ou invasão.", "explicacao": "O Enem valoriza a perspectiva dos povos originários."}, {"id": 2000001386, "trilha": "enem", "materia": "his", "assunto": "História indígena", "tipo": "pergunta", "frente": "O que foram as missões jesuíticas?", "verso": "Aldeamentos onde jesuítas catequizavam indígenas, protegendo-os parcialmente da escravização, mas impondo a cultura europeia.", "explicacao": "Sete Povos das Missões, no Sul."}, {"id": 2000001387, "trilha": "enem", "materia": "his", "assunto": "História africana", "tipo": "pergunta", "frente": "O que foi o tráfico negreiro atlântico?", "verso": "Comércio de africanos escravizados para as Américas; o Brasil recebeu cerca de 4 a 5 milhões de pessoas, o maior número entre os países.", "explicacao": "Foi o último país das Américas a abolir a escravidão."}, {"id": 2000001388, "trilha": "enem", "materia": "his", "assunto": "História africana", "tipo": "pergunta", "frente": "O que a Lei 10.639/2003 tornou obrigatório?", "verso": "O ensino de história e cultura afro-brasileira nas escolas.", "explicacao": "A Lei 11.645/2008 incluiu a cultura indígena."}, {"id": 2000001389, "trilha": "enem", "materia": "his", "assunto": "Patrimônio", "tipo": "pares", "frente": "Patrimônio material x imaterial.", "verso": "Material: bens concretos (edifícios, centros históricos, obras de arte). Imaterial: saberes, celebrações, formas de expressão (samba de roda, frevo, ofício das baianas de acarajé).", "explicacao": "O IPHAN cuida do patrimônio no Brasil."}, {"id": 2000001390, "trilha": "enem", "materia": "his", "assunto": "Revoluções", "tipo": "pergunta", "frente": "O que foi a Revolução Russa de 1917?", "verso": "Revolução que derrubou o czarismo e levou os bolcheviques, liderados por Lênin, ao poder, criando o primeiro Estado socialista.", "explicacao": "Deu origem à URSS em 1922."}, {"id": 2000001391, "trilha": "enem", "materia": "his", "assunto": "Revoluções", "tipo": "pergunta", "frente": "O que foi a Revolução Cubana (1959)?", "verso": "Derrubada do ditador Fulgêncio Batista por guerrilheiros liderados por Fidel Castro; Cuba aproximou-se da URSS.", "explicacao": "Crise dos Mísseis em 1962."}, {"id": 2000001392, "trilha": "enem", "materia": "his", "assunto": "Revoluções", "tipo": "pergunta", "frente": "O que foi a independência do Haiti?", "verso": "Revolução de escravizados (1791–1804) que aboliu a escravidão e criou a primeira república negra.", "explicacao": "Liderança de Toussaint Louverture."}, {"id": 2000001393, "trilha": "enem", "materia": "his", "assunto": "América", "tipo": "pergunta", "frente": "Como foram as independências da América espanhola?", "verso": "Lideradas pelas elites criollas no início do séc. XIX, aproveitando a crise espanhola com Napoleão; o território se fragmentou em vários países.", "explicacao": "Simón Bolívar e San Martín."}, {"id": 2000001394, "trilha": "enem", "materia": "his", "assunto": "América", "tipo": "pergunta", "frente": "Quais civilizações pré-colombianas se destacaram?", "verso": "Maias (América Central), astecas (México) e incas (Andes).", "explicacao": "Tenochtitlán e Machu Picchu."}, {"id": 2000001395, "trilha": "enem", "materia": "his", "assunto": "Trabalho", "tipo": "pergunta", "frente": "O que foi o fordismo?", "verso": "Modelo de produção em massa com linha de montagem e trabalho repetitivo e especializado.", "explicacao": "Henry Ford. O toyotismo trouxe produção flexível e “just in time”."}, {"id": 2000001396, "trilha": "enem", "materia": "his", "assunto": "Trabalho", "tipo": "pergunta", "frente": "O que é a uberização do trabalho?", "verso": "Trabalho mediado por aplicativos, sem vínculo empregatício e com pouca proteção social.", "explicacao": "Tema atual de questões sobre precarização."}, {"id": 2000001397, "trilha": "enem", "materia": "his", "assunto": "Cidadania", "tipo": "pergunta", "frente": "O que foi a Declaração Universal dos Direitos Humanos?", "verso": "Documento da ONU de 1948 que estabeleceu direitos básicos de todas as pessoas.", "explicacao": "Resposta às atrocidades da Segunda Guerra."}, {"id": 2000001398, "trilha": "enem", "materia": "his", "assunto": "Cidadania", "tipo": "pergunta", "frente": "O que foi o movimento pelos direitos civis nos EUA?", "verso": "Luta dos anos 1950–60 contra a segregação racial, com Martin Luther King e Rosa Parks.", "explicacao": "Lei dos Direitos Civis de 1964."}, {"id": 2000001399, "trilha": "enem", "materia": "his", "assunto": "Século XXI", "tipo": "pergunta", "frente": "O que foi a Primavera Árabe?", "verso": "Onda de protestos contra regimes autoritários no Norte da África e Oriente Médio a partir de 2010, organizada em parte pelas redes sociais.", "explicacao": "Começou na Tunísia."}, {"id": 2000001400, "trilha": "enem", "materia": "his", "assunto": "Século XXI", "tipo": "pergunta", "frente": "O que é globalização?", "verso": "Integração econômica, cultural e tecnológica entre os países, acelerada após a Guerra Fria.", "explicacao": "Também amplia desigualdades e homogeneização cultural."}, {"id": 2000001401, "trilha": "enem", "materia": "geo", "assunto": "Cartografia", "tipo": "pares", "frente": "Latitude x longitude.", "verso": "Latitude: distância em graus da Linha do Equador (0° a 90° N ou S). Longitude: distância em graus do Meridiano de Greenwich (0° a 180° L ou O).", "explicacao": "A longitude define os fusos horários."}, {"id": 2000001402, "trilha": "enem", "materia": "geo", "assunto": "Cartografia", "tipo": "pergunta", "frente": "Quantos graus correspondem a cada fuso horário?", "verso": "15°, porque a Terra gira 360° em 24 horas.", "explicacao": "A leste, as horas são adiantadas; a oeste, atrasadas."}, {"id": 2000001403, "trilha": "enem", "materia": "geo", "assunto": "Cartografia", "tipo": "pares", "frente": "Escala grande x escala pequena.", "verso": "Grande (ex.: 1:1.000): mostra área pequena com muitos detalhes. Pequena (ex.: 1:10.000.000): mostra área grande com poucos detalhes.", "explicacao": "Quanto maior o denominador, menor a escala."}, {"id": 2000001404, "trilha": "enem", "materia": "geo", "assunto": "Cartografia", "tipo": "pares", "frente": "Projeção de Mercator x de Peters.", "verso": "Mercator: conforme, preserva formas e distorce áreas perto dos polos (Europa parece maior). Peters: equivalente, preserva áreas e distorce formas.", "explicacao": "Mercator é útil para navegação."}, {"id": 2000001405, "trilha": "enem", "materia": "geo", "assunto": "Cartografia", "tipo": "pergunta", "frente": "O que são curvas de nível?", "verso": "Linhas que ligam pontos de mesma altitude num mapa.", "explicacao": "Curvas próximas indicam relevo íngreme."}, {"id": 2000001406, "trilha": "enem", "materia": "geo", "assunto": "Geologia", "tipo": "pergunta", "frente": "O que é a teoria da tectônica de placas?", "verso": "A crosta terrestre é dividida em placas que se movem sobre o manto, causando terremotos, vulcões e formação de montanhas.", "explicacao": "O Brasil fica no centro da Placa Sul-Americana, com pouca atividade sísmica."}, {"id": 2000001407, "trilha": "enem", "materia": "geo", "assunto": "Geologia", "tipo": "pares", "frente": "Rochas magmáticas x sedimentares x metamórficas.", "verso": "Magmáticas: solidificação do magma (granito, basalto). Sedimentares: acúmulo de sedimentos, podem ter fósseis e petróleo (arenito, calcário). Metamórficas: transformação por pressão e calor (mármore, gnaisse).", "explicacao": ""}, {"id": 2000001408, "trilha": "enem", "materia": "geo", "assunto": "Geologia", "tipo": "pares", "frente": "Intemperismo físico x químico.", "verso": "Físico: desagregação por variação de temperatura e outros agentes, sem mudar a composição (comum em desertos). Químico: decomposição por reações com água (comum em clima quente e úmido).", "explicacao": "O intemperismo químico forma solos profundos nos trópicos."}, {"id": 2000001409, "trilha": "enem", "materia": "geo", "assunto": "Relevo", "tipo": "pergunta", "frente": "Quais as principais formas de relevo do Brasil?", "verso": "Planaltos, planícies e depressões.", "explicacao": "Classificação de Jurandyr Ross."}, {"id": 2000001410, "trilha": "enem", "materia": "geo", "assunto": "Relevo", "tipo": "pergunta", "frente": "O que é erosão e o que a intensifica?", "verso": "Desgaste e transporte do solo pela água, vento ou gelo; intensificada pelo desmatamento e manejo inadequado.", "explicacao": "Voçorocas são erosões profundas."}, {"id": 2000001411, "trilha": "enem", "materia": "geo", "assunto": "Solos", "tipo": "pergunta", "frente": "O que é lixiviação?", "verso": "Lavagem dos nutrientes do solo pela água da chuva, empobrecendo-o.", "explicacao": "Comum em áreas de chuva intensa sem cobertura vegetal."}, {"id": 2000001412, "trilha": "enem", "materia": "geo", "assunto": "Solos", "tipo": "pergunta", "frente": "Quais práticas conservam o solo agrícola?", "verso": "Plantio direto, curvas de nível, terraceamento, rotação de culturas e cobertura vegetal.", "explicacao": ""}, {"id": 2000001413, "trilha": "enem", "materia": "geo", "assunto": "Clima", "tipo": "pares", "frente": "Tempo x clima.", "verso": "Tempo: estado momentâneo da atmosfera (hoje está chovendo). Clima: padrão de longo prazo, cerca de 30 anos de observação.", "explicacao": ""}, {"id": 2000001414, "trilha": "enem", "materia": "geo", "assunto": "Clima", "tipo": "pergunta", "frente": "Quais fatores influenciam o clima?", "verso": "Latitude, altitude, maritimidade e continentalidade, massas de ar, correntes marítimas e vegetação.", "explicacao": "Quanto maior a altitude, menor a temperatura."}, {"id": 2000001415, "trilha": "enem", "materia": "geo", "assunto": "Clima", "tipo": "pergunta", "frente": "O que é a inversão térmica?", "verso": "Uma camada de ar quente fica sobre uma camada de ar frio junto ao solo, impedindo a dispersão de poluentes.", "explicacao": "Mais comum no inverno, em grandes cidades."}, {"id": 2000001416, "trilha": "enem", "materia": "geo", "assunto": "Clima", "tipo": "pergunta", "frente": "O que são ilhas de calor?", "verso": "Áreas urbanas mais quentes que o entorno, por causa do asfalto, concreto, poucas áreas verdes e emissões.", "explicacao": "Arborização ajuda a reduzir."}, {"id": 2000001417, "trilha": "enem", "materia": "geo", "assunto": "Clima", "tipo": "pergunta", "frente": "O que é o El Niño e seus efeitos no Brasil?", "verso": "Aquecimento anormal das águas do Pacífico Equatorial; provoca secas no Norte e Nordeste e chuvas excessivas no Sul.", "explicacao": "La Niña tem efeitos em geral opostos."}, {"id": 2000001418, "trilha": "enem", "materia": "geo", "assunto": "Clima", "tipo": "pergunta", "frente": "O que são os “rios voadores”?", "verso": "Fluxos de umidade transportados pelo ar da Amazônia para o Centro-Sul, levando chuvas.", "explicacao": "O desmatamento ameaça esse regime de chuvas."}, {"id": 2000001419, "trilha": "enem", "materia": "geo", "assunto": "Clima", "tipo": "pergunta", "frente": "Qual o clima predominante no sertão nordestino?", "verso": "Semiárido: chuvas baixas e irregulares e altas temperaturas.", "explicacao": "Polígono das Secas."}, {"id": 2000001420, "trilha": "enem", "materia": "geo", "assunto": "Hidrografia", "tipo": "pergunta", "frente": "O que é uma bacia hidrográfica?", "verso": "Área drenada por um rio principal e seus afluentes.", "explicacao": "Divisor de águas separa as bacias."}, {"id": 2000001421, "trilha": "enem", "materia": "geo", "assunto": "Hidrografia", "tipo": "pergunta", "frente": "Por que o Brasil tem grande potencial hidrelétrico?", "verso": "Muitos rios de planalto, caudalosos e com desníveis.", "explicacao": "Hidrelétricas são a principal fonte da matriz elétrica brasileira."}, {"id": 2000001422, "trilha": "enem", "materia": "geo", "assunto": "Hidrografia", "tipo": "pergunta", "frente": "Qual a importância do rio São Francisco?", "verso": "Atravessa o semiárido, é perene, gera energia e, pela transposição, leva água a outras áreas do semiárido.", "explicacao": "Chamado de “rio da integração nacional”."}, {"id": 2000001423, "trilha": "enem", "materia": "geo", "assunto": "Hidrografia", "tipo": "pergunta", "frente": "O que é o Aquífero Guarani?", "verso": "Uma das maiores reservas de água subterrânea do mundo, sob Brasil, Argentina, Paraguai e Uruguai.", "explicacao": "Ameaçado pela contaminação por agrotóxicos."}, {"id": 2000001424, "trilha": "enem", "materia": "geo", "assunto": "População", "tipo": "pergunta", "frente": "O que é transição demográfica?", "verso": "A passagem de altas taxas de natalidade e mortalidade para taxas baixas, com envelhecimento da população.", "explicacao": "O Brasil está em fase avançada."}, {"id": 2000001425, "trilha": "enem", "materia": "geo", "assunto": "População", "tipo": "pergunta", "frente": "O que indica uma pirâmide etária de base estreita e topo largo?", "verso": "População envelhecida: natalidade baixa e expectativa de vida alta.", "explicacao": "Base larga indica muitos jovens."}, {"id": 2000001426, "trilha": "enem", "materia": "geo", "assunto": "População", "tipo": "pergunta", "frente": "Quais os desafios do envelhecimento da população?", "verso": "Pressão sobre a previdência e o sistema de saúde e menor proporção de pessoas em idade ativa.", "explicacao": "Bônus demográfico é a fase com muitos adultos em idade ativa."}, {"id": 2000001427, "trilha": "enem", "materia": "geo", "assunto": "População", "tipo": "pergunta", "frente": "O que é êxodo rural?", "verso": "Migração em massa do campo para as cidades.", "explicacao": "No Brasil, intenso entre 1950 e 1980, com a mecanização do campo."}, {"id": 2000001428, "trilha": "enem", "materia": "geo", "assunto": "População", "tipo": "pergunta", "frente": "O que é o IDH?", "verso": "Índice de Desenvolvimento Humano, que combina saúde (expectativa de vida), educação e renda.", "explicacao": "Vai de 0 a 1."}, {"id": 2000001429, "trilha": "enem", "materia": "geo", "assunto": "Urbanização", "tipo": "pares", "frente": "Metrópole x megalópole x conurbação.", "verso": "Metrópole: grande cidade que polariza uma região. Megalópole: junção de metrópoles. Conurbação: encontro físico das manchas urbanas de cidades vizinhas.", "explicacao": "Rio–São Paulo forma uma megalópole em formação."}, {"id": 2000001430, "trilha": "enem", "materia": "geo", "assunto": "Urbanização", "tipo": "pergunta", "frente": "O que é segregação socioespacial?", "verso": "A separação dos grupos sociais no espaço urbano: ricos em áreas valorizadas, pobres em periferias e áreas de risco.", "explicacao": "Condomínios fechados e favelas lado a lado."}, {"id": 2000001431, "trilha": "enem", "materia": "geo", "assunto": "Urbanização", "tipo": "pergunta", "frente": "O que é gentrificação?", "verso": "Valorização de uma área urbana que expulsa os moradores mais pobres pelo aumento dos preços.", "explicacao": ""}, {"id": 2000001432, "trilha": "enem", "materia": "geo", "assunto": "Urbanização", "tipo": "pergunta", "frente": "Por que as enchentes urbanas são frequentes?", "verso": "Impermeabilização do solo, ocupação de várzeas, canalização dos rios e lixo nos bueiros.", "explicacao": ""}, {"id": 2000001433, "trilha": "enem", "materia": "geo", "assunto": "Agropecuária", "tipo": "pares", "frente": "Agricultura familiar x agronegócio.", "verso": "Familiar: pequenas propriedades, mão de obra da família, produz boa parte dos alimentos do mercado interno. Agronegócio: grandes propriedades, mecanização, monocultura para exportação (commodities).", "explicacao": ""}, {"id": 2000001434, "trilha": "enem", "materia": "geo", "assunto": "Agropecuária", "tipo": "pergunta", "frente": "O que foi a Revolução Verde?", "verso": "Modernização agrícola com sementes melhoradas, fertilizantes, agrotóxicos e máquinas, aumentando a produtividade.", "explicacao": "Gerou concentração de terras e impactos ambientais."}, {"id": 2000001435, "trilha": "enem", "materia": "geo", "assunto": "Agropecuária", "tipo": "pergunta", "frente": "O que é a fronteira agrícola?", "verso": "Área de expansão da agropecuária sobre a vegetação nativa, hoje sobre o Cerrado e a Amazônia.", "explicacao": "MATOPIBA: Maranhão, Tocantins, Piauí e Bahia."}, {"id": 2000001436, "trilha": "enem", "materia": "geo", "assunto": "Agropecuária", "tipo": "pergunta", "frente": "O que é a estrutura fundiária concentrada?", "verso": "Poucas pessoas detêm grande parte das terras (latifúndios), enquanto muitos têm pouca ou nenhuma terra.", "explicacao": "Origem nas sesmarias e na Lei de Terras de 1850."}, {"id": 2000001437, "trilha": "enem", "materia": "geo", "assunto": "Indústria", "tipo": "pergunta", "frente": "O que é a desconcentração industrial no Brasil?", "verso": "A migração de indústrias do Sudeste para outras regiões em busca de incentivos fiscais, mão de obra barata e menos sindicatos.", "explicacao": "Guerra fiscal entre estados."}, {"id": 2000001438, "trilha": "enem", "materia": "geo", "assunto": "Energia", "tipo": "pergunta", "frente": "Qual a vantagem e a desvantagem das hidrelétricas?", "verso": "Vantagem: renovável e com baixa emissão na operação. Desvantagem: alaga áreas, desloca populações e afeta ecossistemas.", "explicacao": "Belo Monte é exemplo de controvérsia."}, {"id": 2000001439, "trilha": "enem", "materia": "geo", "assunto": "Energia", "tipo": "pergunta", "frente": "Por que a energia eólica cresce no Nordeste?", "verso": "Pela regularidade e intensidade dos ventos.", "explicacao": "O Nordeste concentra a maior parte dos parques eólicos do país."}, {"id": 2000001440, "trilha": "enem", "materia": "geo", "assunto": "Energia", "tipo": "pares", "frente": "Matriz energética x matriz elétrica.", "verso": "Matriz energética: todas as fontes de energia usadas (transporte, indústria etc.). Matriz elétrica: só as fontes para gerar eletricidade.", "explicacao": "A matriz elétrica brasileira é majoritariamente renovável."}, {"id": 2000001441, "trilha": "enem", "materia": "geo", "assunto": "Meio ambiente", "tipo": "pergunta", "frente": "O que é desenvolvimento sustentável?", "verso": "Atender às necessidades atuais sem comprometer as das gerações futuras.", "explicacao": "Relatório Brundtland (1987)."}, {"id": 2000001442, "trilha": "enem", "materia": "geo", "assunto": "Meio ambiente", "tipo": "pergunta", "frente": "O que foi o Acordo de Paris (2015)?", "verso": "Compromisso global de limitar o aquecimento bem abaixo de 2 °C, buscando 1,5 °C, com metas nacionais de redução de emissões.", "explicacao": "Substituiu o Protocolo de Kyoto."}, {"id": 2000001443, "trilha": "enem", "materia": "geo", "assunto": "Meio ambiente", "tipo": "pergunta", "frente": "O que é desertificação?", "verso": "Degradação de terras em regiões áridas e semiáridas por causas climáticas e humanas (desmatamento, uso inadequado do solo).", "explicacao": "No Brasil, afeta áreas do semiárido nordestino."}, {"id": 2000001444, "trilha": "enem", "materia": "geo", "assunto": "Meio ambiente", "tipo": "pergunta", "frente": "O que é pegada ecológica?", "verso": "Medida da área produtiva necessária para sustentar o consumo de uma pessoa ou país.", "explicacao": ""}, {"id": 2000001445, "trilha": "enem", "materia": "geo", "assunto": "Geopolítica", "tipo": "pergunta", "frente": "O que é o Mercosul?", "verso": "Bloco econômico criado em 1991 por Brasil, Argentina, Paraguai e Uruguai.", "explicacao": "É uma união aduaneira imperfeita."}, {"id": 2000001446, "trilha": "enem", "materia": "geo", "assunto": "Geopolítica", "tipo": "pergunta", "frente": "O que é a União Europeia?", "verso": "Bloco econômico e político com livre circulação de pessoas, mercadorias e capitais e moeda comum (euro) em parte dos países.", "explicacao": "O Reino Unido saiu em 2020 (Brexit)."}, {"id": 2000001447, "trilha": "enem", "materia": "geo", "assunto": "Geopolítica", "tipo": "pergunta", "frente": "O que são os BRICS?", "verso": "Grupo de países emergentes: inicialmente Brasil, Rússia, Índia, China e África do Sul, ampliado a partir de 2024.", "explicacao": "Foco em cooperação econômica e maior peso no cenário global."}, {"id": 2000001448, "trilha": "enem", "materia": "geo", "assunto": "Geopolítica", "tipo": "pergunta", "frente": "O que é xenofobia?", "verso": "Aversão ou preconceito contra estrangeiros.", "explicacao": "Tema comum em questões sobre migrações e refugiados."}, {"id": 2000001449, "trilha": "enem", "materia": "geo", "assunto": "Geopolítica", "tipo": "pares", "frente": "Refugiado x migrante econômico.", "verso": "Refugiado: foge de perseguição, guerra ou violação grave de direitos, com proteção internacional. Migrante econômico: muda em busca de trabalho e melhores condições.", "explicacao": "Brasil recebeu muitos venezuelanos e haitianos."}, {"id": 2000001450, "trilha": "enem", "materia": "geo", "assunto": "Geopolítica", "tipo": "pergunta", "frente": "O que é a Divisão Internacional do Trabalho?", "verso": "A especialização dos países na economia mundial: alguns exportam produtos industrializados e tecnologia, outros matérias-primas.", "explicacao": "O Brasil ainda exporta muitas commodities."}, {"id": 2000001451, "trilha": "enem", "materia": "geo", "assunto": "Transportes", "tipo": "pergunta", "frente": "Por que o predomínio do transporte rodoviário é um problema no Brasil?", "verso": "É mais caro para longas distâncias e cargas pesadas, polui mais e exige manutenção constante das estradas.", "explicacao": "Ferrovias e hidrovias são mais eficientes para grãos e minérios."}, {"id": 2000001452, "trilha": "enem", "materia": "geo", "assunto": "Regiões", "tipo": "pergunta", "frente": "Quais as regiões geoeconômicas do Brasil?", "verso": "Amazônia, Nordeste e Centro-Sul.", "explicacao": "Proposta de Pedro Geiger (1967), que não segue os limites estaduais."}, {"id": 2000001453, "trilha": "enem", "materia": "geo", "assunto": "Regiões", "tipo": "pergunta", "frente": "Quais as sub-regiões do Nordeste?", "verso": "Zona da Mata, Agreste, Sertão e Meio-Norte.", "explicacao": "Agreste: transição entre a Zona da Mata e o Sertão."}, {"id": 2000001454, "trilha": "enem", "materia": "geo", "assunto": "Indústria 4.0", "tipo": "pergunta", "frente": "O que é a indústria 4.0?", "verso": "Produção com automação avançada, internet das coisas, inteligência artificial e análise de dados.", "explicacao": "Pode reduzir empregos tradicionais e exigir novas qualificações."}, {"id": 2000001455, "trilha": "enem", "materia": "geo", "assunto": "Recursos", "tipo": "pergunta", "frente": "O que é o pré-sal?", "verso": "Reservas de petróleo em águas ultraprofundas, abaixo de uma camada de sal, no litoral do Sudeste.", "explicacao": "Descoberto em 2006."}, {"id": 2000001456, "trilha": "enem", "materia": "fil", "assunto": "Filosofia antiga", "tipo": "pergunta", "frente": "O que buscavam os filósofos pré-socráticos?", "verso": "A arché: o princípio fundamental de todas as coisas, explicado pela razão e não pelos mitos.", "explicacao": "Tales: água; Heráclito: fogo e o devir; Demócrito: átomos."}, {"id": 2000001457, "trilha": "enem", "materia": "fil", "assunto": "Filosofia antiga", "tipo": "pares", "frente": "Heráclito x Parmênides.", "verso": "Heráclito: tudo flui, a realidade é mudança constante (“ninguém se banha duas vezes no mesmo rio”). Parmênides: o ser é imutável; a mudança é ilusão dos sentidos.", "explicacao": ""}, {"id": 2000001458, "trilha": "enem", "materia": "fil", "assunto": "Filosofia antiga", "tipo": "pergunta", "frente": "Qual era o método de Sócrates?", "verso": "A maiêutica: por perguntas, levar o interlocutor a reconhecer a própria ignorância (ironia) e a “dar à luz” ideias.", "explicacao": "“Só sei que nada sei”."}, {"id": 2000001459, "trilha": "enem", "materia": "fil", "assunto": "Filosofia antiga", "tipo": "pergunta", "frente": "O que é o mito da caverna de Platão?", "verso": "Alegoria em que prisioneiros só veem sombras; quem sai da caverna conhece a verdade. Representa a passagem da opinião (doxa) ao conhecimento (episteme).", "explicacao": "Mundo sensível x mundo das ideias."}, {"id": 2000001460, "trilha": "enem", "materia": "fil", "assunto": "Filosofia antiga", "tipo": "pergunta", "frente": "O que é ética para Aristóteles?", "verso": "A busca da felicidade (eudaimonia) por meio da virtude, que é o justo meio entre dois extremos.", "explicacao": "Ex.: coragem entre covardia e temeridade."}, {"id": 2000001461, "trilha": "enem", "materia": "fil", "assunto": "Filosofia antiga", "tipo": "pergunta", "frente": "O que Aristóteles quis dizer com “o homem é um animal político”?", "verso": "Que o ser humano só se realiza plenamente vivendo em sociedade, na pólis.", "explicacao": ""}, {"id": 2000001462, "trilha": "enem", "materia": "fil", "assunto": "Filosofia antiga", "tipo": "pares", "frente": "Sofistas x Sócrates.", "verso": "Sofistas: mestres da retórica, cobravam pelo ensino e defendiam o relativismo (“o homem é a medida de todas as coisas”, Protágoras). Sócrates: buscava a verdade e criticava a persuasão sem compromisso com ela.", "explicacao": ""}, {"id": 2000001463, "trilha": "enem", "materia": "fil", "assunto": "Filosofia antiga", "tipo": "pergunta", "frente": "O que propunham os estoicos?", "verso": "Viver de acordo com a natureza e a razão, aceitando o que não se pode controlar, com serenidade (apatia).", "explicacao": "Sêneca, Epicteto, Marco Aurélio."}, {"id": 2000001464, "trilha": "enem", "materia": "fil", "assunto": "Filosofia antiga", "tipo": "pergunta", "frente": "O que defendia Epicuro?", "verso": "A felicidade como ausência de dor e perturbação (ataraxia), com prazeres simples e moderados.", "explicacao": "Não é hedonismo desenfreado."}, {"id": 2000001465, "trilha": "enem", "materia": "fil", "assunto": "Filosofia medieval", "tipo": "pares", "frente": "Santo Agostinho x São Tomás de Aquino.", "verso": "Agostinho: patrística, influência de Platão, fé acima da razão. Tomás: escolástica, influência de Aristóteles, conciliação entre fé e razão (cinco vias para provar Deus).", "explicacao": ""}, {"id": 2000001466, "trilha": "enem", "materia": "fil", "assunto": "Filosofia moderna", "tipo": "pergunta", "frente": "O que significa “Penso, logo existo”?", "verso": "Para Descartes, a única certeza indubitável após a dúvida metódica é a de que o sujeito pensa e, portanto, existe.", "explicacao": "Racionalismo."}, {"id": 2000001467, "trilha": "enem", "materia": "fil", "assunto": "Filosofia moderna", "tipo": "pares", "frente": "Racionalismo x empirismo.", "verso": "Racionalismo: o conhecimento vem da razão, com ideias inatas (Descartes). Empirismo: vem da experiência sensível; a mente nasce como “tábula rasa” (Locke, Hume).", "explicacao": "Kant tenta conciliar os dois."}, {"id": 2000001468, "trilha": "enem", "materia": "fil", "assunto": "Filosofia moderna", "tipo": "pergunta", "frente": "O que é o imperativo categórico de Kant?", "verso": "Agir apenas segundo uma regra que você queira que se torne lei universal; tratar a humanidade sempre como fim, nunca apenas como meio.", "explicacao": "Ética do dever."}, {"id": 2000001469, "trilha": "enem", "materia": "fil", "assunto": "Filosofia moderna", "tipo": "pergunta", "frente": "O que é o Esclarecimento (Aufklärung) para Kant?", "verso": "A saída do ser humano de sua menoridade, pela coragem de usar o próprio entendimento: “Ouse saber!” (Sapere aude).", "explicacao": ""}, {"id": 2000001470, "trilha": "enem", "materia": "fil", "assunto": "Política", "tipo": "pergunta", "frente": "Qual a ideia central de “O Príncipe”, de Maquiavel?", "verso": "A política tem lógica própria, separada da moral religiosa; o governante deve usar virtù e aproveitar a fortuna para manter o poder.", "explicacao": "“É melhor ser temido que amado”, se não puder ser os dois."}, {"id": 2000001471, "trilha": "enem", "materia": "fil", "assunto": "Política", "tipo": "pares", "frente": "Hobbes x Locke x Rousseau (contratualistas).", "verso": "Hobbes: estado de natureza é guerra de todos contra todos; o Estado absoluto (Leviatã) garante a paz. Locke: direitos naturais (vida, liberdade, propriedade); o governo deve protegê-los, e há direito de resistência. Rousseau: o homem nasce bom e a sociedade o corrompe; soberania da vontade geral.", "explicacao": ""}, {"id": 2000001472, "trilha": "enem", "materia": "fil", "assunto": "Política", "tipo": "pergunta", "frente": "O que defendia Montesquieu?", "verso": "A separação dos poderes em Executivo, Legislativo e Judiciário, para evitar abusos.", "explicacao": "“O Espírito das Leis”."}, {"id": 2000001473, "trilha": "enem", "materia": "fil", "assunto": "Filosofia contemporânea", "tipo": "pergunta", "frente": "O que significa “a existência precede a essência” (Sartre)?", "verso": "O ser humano primeiro existe e depois se define por suas escolhas; está “condenado a ser livre” e é responsável por si.", "explicacao": "Existencialismo."}, {"id": 2000001474, "trilha": "enem", "materia": "fil", "assunto": "Filosofia contemporânea", "tipo": "pergunta", "frente": "O que Nietzsche quis dizer com “Deus está morto”?", "verso": "Que os valores tradicionais cristãos perderam força na modernidade, abrindo espaço para criar novos valores.", "explicacao": "Crítica à moral de rebanho."}, {"id": 2000001475, "trilha": "enem", "materia": "fil", "assunto": "Filosofia contemporânea", "tipo": "pergunta", "frente": "O que é a “banalidade do mal” para Hannah Arendt?", "verso": "A ideia de que grandes crimes podem ser cometidos por pessoas comuns que apenas obedecem e não refletem sobre seus atos.", "explicacao": "Inspirada no julgamento do nazista Eichmann."}, {"id": 2000001476, "trilha": "enem", "materia": "fil", "assunto": "Filosofia contemporânea", "tipo": "pergunta", "frente": "O que é indústria cultural (Adorno e Horkheimer)?", "verso": "Produção de cultura como mercadoria padronizada, que entretém, mas aliena e reduz o senso crítico.", "explicacao": "Escola de Frankfurt."}, {"id": 2000001477, "trilha": "enem", "materia": "fil", "assunto": "Filosofia contemporânea", "tipo": "pergunta", "frente": "O que Simone de Beauvoir quis dizer com “Ninguém nasce mulher: torna-se mulher”?", "verso": "Que o papel feminino é construção social e cultural, não um destino biológico.", "explicacao": "“O segundo sexo” (1949)."}, {"id": 2000001478, "trilha": "enem", "materia": "fil", "assunto": "Filosofia contemporânea", "tipo": "pergunta", "frente": "O que Foucault analisou em “Vigiar e punir”?", "verso": "Como o poder disciplinar molda corpos e comportamentos em prisões, escolas, quartéis e hospitais, por vigilância e normalização.", "explicacao": "Panóptico como modelo."}, {"id": 2000001479, "trilha": "enem", "materia": "fil", "assunto": "Ética", "tipo": "pares", "frente": "Ética x moral.", "verso": "Moral: conjunto de normas e costumes de um grupo. Ética: reflexão filosófica sobre essas normas e sobre o agir.", "explicacao": ""}, {"id": 2000001480, "trilha": "enem", "materia": "fil", "assunto": "Ética", "tipo": "pergunta", "frente": "O que é o utilitarismo?", "verso": "Ética que considera correta a ação que produz a maior felicidade para o maior número de pessoas.", "explicacao": "Bentham e Stuart Mill. Ética das consequências."}, {"id": 2000001481, "trilha": "enem", "materia": "fil", "assunto": "Lógica", "tipo": "pergunta", "frente": "O que é um silogismo?", "verso": "Raciocínio com duas premissas e uma conclusão: “Todo homem é mortal; Sócrates é homem; logo, Sócrates é mortal”.", "explicacao": "Lógica aristotélica."}, {"id": 2000001482, "trilha": "enem", "materia": "fil", "assunto": "Lógica", "tipo": "pares", "frente": "Dedução x indução.", "verso": "Dedução: do geral para o particular; se as premissas forem verdadeiras, a conclusão é necessária. Indução: de casos particulares para uma generalização provável.", "explicacao": "A ciência usa muito a indução."}, {"id": 2000001483, "trilha": "enem", "materia": "fil", "assunto": "Sociologia clássica", "tipo": "pergunta", "frente": "O que é fato social para Durkheim?", "verso": "Maneiras de agir, pensar e sentir exteriores ao indivíduo, gerais e coercitivas.", "explicacao": "Ex.: leis, língua, costumes."}, {"id": 2000001484, "trilha": "enem", "materia": "fil", "assunto": "Sociologia clássica", "tipo": "pares", "frente": "Solidariedade mecânica x orgânica (Durkheim).", "verso": "Mecânica: sociedades simples, unidas pela semelhança. Orgânica: sociedades complexas, unidas pela interdependência da divisão do trabalho.", "explicacao": ""}, {"id": 2000001485, "trilha": "enem", "materia": "fil", "assunto": "Sociologia clássica", "tipo": "pergunta", "frente": "O que é mais-valia para Marx?", "verso": "O valor produzido pelo trabalhador além do que recebe como salário, apropriado pelo capitalista.", "explicacao": "Base da exploração no capitalismo."}, {"id": 2000001486, "trilha": "enem", "materia": "fil", "assunto": "Sociologia clássica", "tipo": "pergunta", "frente": "O que é alienação do trabalho para Marx?", "verso": "O trabalhador não se reconhece no que produz, nem controla o processo e o produto do próprio trabalho.", "explicacao": ""}, {"id": 2000001487, "trilha": "enem", "materia": "fil", "assunto": "Sociologia clássica", "tipo": "pergunta", "frente": "O que é ação social para Max Weber?", "verso": "Ação orientada pelo comportamento de outros, com sentido para quem age.", "explicacao": "Tipos: racional com relação a fins, a valores, afetiva e tradicional."}, {"id": 2000001488, "trilha": "enem", "materia": "fil", "assunto": "Sociologia clássica", "tipo": "pares", "frente": "Dominação tradicional x carismática x legal (Weber).", "verso": "Tradicional: baseada nos costumes (monarquias). Carismática: nas qualidades extraordinárias do líder. Legal-racional: em regras e leis impessoais (burocracia).", "explicacao": ""}, {"id": 2000001489, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é etnocentrismo?", "verso": "Julgar outras culturas a partir dos valores da própria, considerada superior.", "explicacao": "Seu oposto é o relativismo cultural."}, {"id": 2000001490, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é cultura para a antropologia?", "verso": "Tudo o que é criado e transmitido socialmente: crenças, valores, técnicas, costumes, artes.", "explicacao": "Não é algo “superior” de alguns grupos."}, {"id": 2000001491, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pares", "frente": "Estratificação: casta x estamento x classe social.", "verso": "Casta: posição pelo nascimento, sem mobilidade. Estamento: por honra e tradição, pouca mobilidade (sociedade feudal). Classe: posição econômica, com mobilidade possível.", "explicacao": ""}, {"id": 2000001492, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é racismo estrutural?", "verso": "Racismo presente no funcionamento normal das instituições e da sociedade, produzindo desigualdades mesmo sem intenção individual.", "explicacao": "Silvio Almeida popularizou o termo no Brasil."}, {"id": 2000001493, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é o “mito da democracia racial”?", "verso": "A ideia falsa de que no Brasil não há racismo por causa da miscigenação, que esconde as desigualdades raciais.", "explicacao": "Crítica de Florestan Fernandes à visão associada a Gilberto Freyre."}, {"id": 2000001494, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é o “homem cordial” de Sérgio Buarque de Holanda?", "verso": "Brasileiro que age pela emoção e por relações pessoais, misturando público e privado, e não por regras impessoais.", "explicacao": "“Raízes do Brasil” (1936). Cordial vem de coração, não de gentileza."}, {"id": 2000001495, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que são movimentos sociais?", "verso": "Ações coletivas organizadas para reivindicar direitos ou mudanças sociais.", "explicacao": "Ex.: movimento negro, feminista, sem-terra, LGBTQIA+."}, {"id": 2000001496, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é cidadania segundo T. H. Marshall?", "verso": "Conjunto de direitos civis, políticos e sociais.", "explicacao": "Na Inglaterra surgiram nessa ordem; José Murilo de Carvalho mostra que no Brasil a ordem foi diferente."}, {"id": 2000001497, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é sociedade do espetáculo (Guy Debord)?", "verso": "Sociedade em que as relações sociais são mediadas por imagens e a aparência substitui a experiência real.", "explicacao": ""}, {"id": 2000001498, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pergunta", "frente": "O que é modernidade líquida (Zygmunt Bauman)?", "verso": "Época de relações, empregos e identidades frágeis e passageiras, marcada pelo consumo e pela insegurança.", "explicacao": ""}, {"id": 2000001499, "trilha": "enem", "materia": "fil", "assunto": "Sociologia", "tipo": "pares", "frente": "Socialização primária x secundária.", "verso": "Primária: na infância, pela família. Secundária: ao longo da vida, por escola, trabalho, religião, mídia.", "explicacao": ""}, {"id": 2000001500, "trilha": "enem", "materia": "fil", "assunto": "Política", "tipo": "pares", "frente": "Democracia direta x representativa.", "verso": "Direta: os cidadãos decidem diretamente (Atenas). Representativa: elegem representantes para decidir por eles.", "explicacao": "O Brasil tem mecanismos de participação direta: plebiscito, referendo e iniciativa popular."}]$c$::jsonb) as x(id integer, trilha text, materia text, assunto text, tipo text, frente text, verso text, explicacao text)
on conflict (id) do update set trilha = excluded.trilha, materia = excluded.materia, assunto = excluded.assunto, tipo = excluded.tipo,
  frente = excluded.frente, verso = excluded.verso, explicacao = excluded.explicacao, ativa = true, atualizado_em = now();

select trilha, count(*) as cartoes, public.cartoes_versao() as versao from public.cartoes where ativa group by trilha;
